import{_ as a,O as r,o,c as n,a as s,i,f as d}from"./chunks/framework.fmIt2z2h.js";const g=JSON.parse('{"title":"第十二部分　条件前瞻与有限选择","description":"","frontmatter":{"title":"第十二部分　条件前瞻与有限选择","xkChars":7761,"xkLessons":{"intro-12-part":{"title":"第十二部分　条件前瞻与有限选择","lead":"前一部分画出可能路径，这一部分进一步问：哪些未来判断愿意接受到期检验？在什么价值与保护条件下，可以比较和推荐行动？两问相连，但预测不提供让别人承担成本的权力。","explanation":["原文定位：第2446—2449行；原文锚点 part_12；短引文：‘把二者分成不同合同’。本题源切片逐字附后，讲解与原文分开。","条件前瞻在目标、期限和证据边界内承担可失败的未来判断。可失败意味着到期存在明确的支持、未支持或未决条件，不能把所有路径都算成功，也不能无限延长期限。第12.2—12.7将规定登记、局部可预测性、基线、表达、评价与失败语义。","有限选择在明示价值、保护和授权边界内比较可做什么、怎样做、何时停及何时不做。第12.8以后把前瞻接入方案、分配后果、可逆性与现实采用程序；不行动也要比较，不能默认其没有成本。","两者放在一起形成工作闭环：预测给选择提供条件后果，行动与响应可能改变未来资料，结果再帮助纠正判断。不同合同则防止跨层偷换：某后果很可能发生，不代表它应被促成或任何人可强迫别人为避免它付出。","比较推荐本身可以是完整分析交付。只要证据、规范前提、代价和限制明确，就可给有依据的首选、否决或暂缓意见，不必因为尚无执行权就只剩问题清单。但现实采用与执行另需适用的保护、复核和有效授权；“只是建议”也不能掩盖可预见的高影响用途。","本部分不承诺全世界可预测，也不把选择理解为模型统一所有价值。它允许有限答案、未知、不可比、多方案与当前不做，并要求明确哪些材料能改变判断。"],"distinctions":[{"leftTitle":"条件前瞻","leftText":"对未来目标承担可失败判断。","rightTitle":"有限选择","rightText":"在明示规范和限制下比较方案。"},{"leftTitle":"供审议推荐","leftText":"可以是明确的分析结论。","rightTitle":"现实采用","rightText":"须独立通过适用保护、复核和授权。"}],"boundaries":["预测可能准而选择仍不正当；选择程序合格也不保证执行成功。","导语是任务边界导航，不提供经验增益定理。"],"questions":["没有执行权是否只能列疑问，不能推荐？","为什么前瞻和选择既相邻又分合同？"],"diagramPath":"/reading-assets/S-12-1/figures/intro-12-part.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"intro-12-part","start_line":2446,"end_line":2449,"startLine":2446,"endLine":2449}],"outputId":"intro-12-part","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["把未来判断变成有目标、期限和评价责任的前瞻合同。","把方案比较的规范、保护、分配及权限条件单独公开。","允许完整的供审议推荐，但不把预测或推荐变成执行许可。","真实结果进入追加回写，原合同和失败记录继续保留。"],"teachingExamples":[{"title":"教学构造：同一预测不足以决定行动","text":"虚构任务预测某排队方案会让平均等待少2分钟，但未知是否使一位无法退出者等待多一小时。这个平均前瞻可以进入比较，却不足以决定应执行；须明确分配、底线、替代方案与权限。即便补齐后分析首选它，也不等于已经调度现实队列。","assumptions":"数字、对象与后果均为教学设定，没有实测或人群试验。","boundary":"不据此给现实服务机构处置建议。"}],"counterexamples":[{"identity":"constructed_boundary","text":"模型预测总体会改善，所以它可以直接命令所有人采用。","effect":"事实后果不自动产生价值前提、权利正当性或执行权限。","sourceIds":["theory"]}],"questionAnswers":[{"question":"没有执行权是否只能列疑问，不能推荐？","answer":"不是，可以在证据与明示规范允许范围内完成供审议推荐，执行身份另列。","basis":"本节原文及上述公开推导"},{"question":"为什么前瞻和选择既相邻又分合同？","answer":"为了让结果接入行动比较与回写，同时阻止预测被偷换成权力。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-1/figures/intro-12-part.png","alt":"条件前瞻，目标／期限／基线，可校准、可失败；有限选择分析，规范／方案／分配，首选与反方；现实采用与执行，保护／复核／授权，停止与补救。并列责任不自动升级；工作可以相连，资格须分别核。","caption":"并列责任不自动升级；工作可以相连，资格须分别核。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。导语图只导航三类责任，不表示推演可以自动授权。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"分部导语规定工作分工和边界，不是独立经验案例命题；具体历史资料放在相关编号单元。"},"openQuestions":[],"taskId":"S-12-1","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2446—2462行；每节精确范围见sourceRefs","claim_support":["intro-12-part：术语、合同、论证责任和原文边界；不据此认证经验事实","12.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"norm","title":"现行原文规范选择及现实采用分工","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§1.4第107—128行；§1.7第147—152行；§4.14.1第908—925行；§14.6第2940—2953行","claim_support":["解释、规范推荐与干涉区分；保护底板；C12与原子J授权的有限范围"],"limits":["属于用户理论程序规定，不替外部法律效力或实际授权。"],"access_status":"read"},{"id":"met2024","title":"Tropical cyclone verification northern hemisphere 2024","url":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024","source_type":"primary","version_or_date":"2024季节报告，页面未标独立发布日期","locator":"§3.3表，DPE(km)，T+24=57；口径见§1 Introduction","claim_support":["2024北大西洋T+24小时平均直接位置误差57千米"],"limits":["运营机构汇总，未独立复算逐案；不代表当前预报，也不赋予现实行动权限。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-12-1/lecture.md","sourcesPath":"/reading-assets/S-12-1/sources.json","sourceSlicePath":"/reading-assets/S-12-1/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-1/diagrams.md"},"12.1":{"title":"12.1　四类输出的隔离","lead":"一句“我认为会这样，所以应该那样”可能偷偷跨了好几道门。本节要求先辨明自己是在解释过去、展开条件、预测未来，还是提出规范选择，每一种都对不同问题负责。","explanation":["原文定位：第2450—2462行；原文锚点 section-12-1；短引文：‘解释、推演、条件前瞻和有限选择必须分别标记’。本题源切片逐字附后，讲解与原文分开。","解释回答已发生什么、可能为何发生，需要对象、尺度、证据、机制与反例。上限是有边界的机制说明，不因为对过去叙述连贯就证明未来同样发生；解释也可能保留多种机制，不能把未知讲成唯一原因。","推演从冻结快照、更新规则、时钟和分叉出发，给条件路径与区分信号。它可以说“若工时和资源条件保持，可能沿这条支推进”，但列出多条路径不等于每条都有概率，更不能在事后挑中一条就说全部推演预测成功。","条件前瞻增加结果前登记、简单基线、目标指标与回写责任。它回答指定期限内哪条路径更值得期待，表达可以是有依据的概率、排序或方向，证据不够则保持未知。可校准、可失败不等于已经校准优秀，二者不能混成一个“可靠”标签。","有限选择的分析需规范前提、证据、真实可比方案、代价及受影响者。现实采用另需N显式规范、PF保护底板、J管辖授权、O1—O4过程与C12桥接资格。这里是调用原文的分工，不是模型自创公权；当这些前提尚未满足时仍可作明确供审议分析，但不得冒称已可执行。","逐门相连不自动升格：解释产生推演候选；推演产生前瞻候选；前瞻提供比较后果；规范与程序支持有限选择；实际执行后仍需停止、回滚和回写。任何一层已有充分材料都可给清楚的有限答案，不要求为了答一个解释问题把所有行动程序跑完。","同一成果可以同时含四类输出，但要按句或按段标身份，来源与支持上限分别写。比如事后发现处理能力下降属于解释材料；假设明天仍低速属于情景；登记明天09:00积压超过阈值的概率属于前瞻；建议先检修属于规范分析。它们可共享资料，却不共享全部资格。","准确率只是针对目标和评价合同的性能，不是道德、法律或代表性资格。一个天气模型的位置误差较小，不说明发布者由此能决定任何人的撤离方式；现实保护行动有自己的主体、权限和程序。这个非蕴含不否定天气预测有用，而是防止把有用性扩成无限权力。"],"distinctions":[{"leftTitle":"解释","leftText":"对已发生现象给有边界机制说明。","rightTitle":"推演","rightText":"从条件出发展开可能路径。"},{"leftTitle":"推演候选","leftText":"列出假设成立的后果。","rightTitle":"已登记前瞻","rightText":"结果前冻结并承担到期评价。"},{"leftTitle":"可评价","leftText":"已有目标与计分合同。","rightTitle":"表现已验证良好","rightText":"要有真实结果与适当复核。"},{"leftTitle":"前瞻排序","leftText":"某后果更值得期待的证据判断。","rightTitle":"推荐排序","rightText":"还要规范、分配、成本与保护。"},{"leftTitle":"有限选择通过","leftText":"相应合同得到支持。","rightTitle":"执行必成功","rightText":"现实偏离仍需停止与回写。"}],"boundaries":["四类输出不是必须依次爬升的价值等级，解释任务可止于解释。","没有权限不等于不能作有限分析；“只是建议”也不免除高影响用途责任。","情景数量、图形复杂度和模型语气不生成概率。","当前预测好坏不替规范正当和外部程序效力。"],"questions":["已登记前瞻是否等于已证明预测优秀？","A概率0.8而有害，能否直接说“应选择A”？","四类输出能否共处一份报告？"],"diagramPath":"/reading-assets/S-12-1/figures/section-12-1.png","caseLinks":[{"title":"2024年北大西洋气旋预报：评价量的边界","href":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024"}],"caseNotes":[{"title":"2024年北大西洋气旋预报：评价量的边界","text":"英国气象局2024年北半球气旋检验报告的北大西洋表列出T+24小时平均直接位置误差57千米。这个具体评价量属于预测表现材料；本讲据此说明，它本身不包含对个别人员的行动授权。","sourceLabel":"Met Office，2024北半球检验报告","sourceUrl":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024","sourceLocator":"§3.3 North Atlantic basin storms，Table of mean error statistics，DPE(km)行T+24列","boundary":"该历史业务统计只支持相应地区、年份、提前量及样本口径；不是个人损害概率、当前天气预报或撤离决策。由指标不推出授权是本讲的逻辑边界说明。","href":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024"}],"sourceRefs":[{"section":"12.1","start_line":2450,"end_line":2462,"startLine":2450,"endLine":2462}],"outputId":"section-12-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["分别声明四类输出的问题、所用输入和可支持结论。","检查从上一层进入下一层新增了哪些证据或规范条件。","前瞻只按冻结目标与期限评价，不把所有情景支计成功。","分析推荐写规范与分配，现实采用另核N/PF/J/O/C12。","执行后仍保留失败、停止和补救责任，不以合格程序保证成功。"],"teachingExamples":[{"title":"教学构造：四句话逐项归位","text":"虚构记录显示昨日到件2、完成1、起点6，因此按无其他流量假设终点7，这是有条件的已发生记录解释。若明日同样条件保持，终点会再增1，是推演。若在结果前冻结“明日09:00是否超过7”、信息截止、基线、评分与信号，并给有依据的判断，才进入条件前瞻。若明确以保障期限和不侵害人员底线为规范，比较检修、延迟、转移和不行动后推荐某项，属于有限选择分析；尚不等于检修已获准或已完成。","assumptions":"全例为教学结构，不提供真实概率；昨日记录也为构造设定。","boundary":"算术正确不证明实际机制，无真实登记与结果不能自称前瞻增益。"},{"title":"数学构造：可能性和偏好可反向排序","text":"虚构事件A概率0.8、B概率0.2，且这些概率由题设给定；价值前提认为A损害严重、B无害。A更可能不代表更应促成，甚至会成为应保护免受的对象。若应对方案会伤害第三方，还需另外比较权利与分配，不能只用0.8决定强制措施。","assumptions":"概率与价值均为纯构造，未估现实事件风险。","boundary":"不推出具体行动，也不把期望利益当唯一规范。"}],"counterexamples":[{"identity":"constructed_boundary","text":"解释过去时机制A成立，所以下次A必然发生。","effect":"适用条件与未来输入可能变化，需另承担前瞻合同。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"最终发生了十条情景中的一条，所以十条都可算预测命中。","effect":"多支探索不等十条成功，必须按事前目标与表达评价。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"模型预测准确，所以它拥有决定他人命运的资格。","effect":"性能不生成规范、代表性、管辖与授权。","sourceIds":["theory"]}],"questionAnswers":[{"question":"已登记前瞻是否等于已证明预测优秀？","answer":"不是，登记只是明确可失败合同，表现还需真实结果、基线和复核。","basis":"本节原文及上述公开推导"},{"question":"A概率0.8而有害，能否直接说“应选择A”？","answer":"不能，概率描述可能性，选择另需规范与可行方案比较。","basis":"本节原文及上述公开推导"},{"question":"四类输出能否共处一份报告？","answer":"可以，但须分别标身份、证据与上限，不能在一句话里隐蔽升级。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-1/figures/section-12-1.png","alt":"解释，已发生什么／为何，机制与反例；推演，若条件成立会怎样，路径与区分信号；条件前瞻，目标／期限／基线，到期可失败；有限选择分析，明示规范与方案，代价及受影响者；现实采用另核，N／PF／J／O／C12，不由预测造权；执行仍可能偏离，停止／回滚／补救，结果追加回写。各卡是输出资格，不是自动升级阶梯；真实行动必须有独立有效依据。","caption":"各卡是输出资格，不是自动升级阶梯；真实行动必须有独立有效依据。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。用分离卡片避免“解释→命令”的视觉直通；交互设想按输出类别显示其缺口。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"一手业务评价表给出具体性能量，便于说明性能证据与规范权限分属不同问题。"},"openQuestions":["本讲未复算逐个气旋预报误差，引用发布方汇总；未作任何现实天气保护指令。"],"taskId":"S-12-1","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2446—2462行；每节精确范围见sourceRefs","claim_support":["intro-12-part：术语、合同、论证责任和原文边界；不据此认证经验事实","12.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"norm","title":"现行原文规范选择及现实采用分工","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§1.4第107—128行；§1.7第147—152行；§4.14.1第908—925行；§14.6第2940—2953行","claim_support":["解释、规范推荐与干涉区分；保护底板；C12与原子J授权的有限范围"],"limits":["属于用户理论程序规定，不替外部法律效力或实际授权。"],"access_status":"read"},{"id":"met2024","title":"Tropical cyclone verification northern hemisphere 2024","url":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024","source_type":"primary","version_or_date":"2024季节报告，页面未标独立发布日期","locator":"§3.3表，DPE(km)，T+24=57；口径见§1 Introduction","claim_support":["2024北大西洋T+24小时平均直接位置误差57千米"],"limits":["运营机构汇总，未独立复算逐案；不代表当前预报，也不赋予现实行动权限。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-12-1/lecture.md","sourcesPath":"/reading-assets/S-12-1/sources.json","sourceSlicePath":"/reading-assets/S-12-1/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-1/diagrams.md"},"12.2":{"title":"12.2　条件前瞻登记","lead":"先把什么算预测、什么时候算结束、怎样算对错写清，再等待结果。否则“关系会变好”可以永远解释为某处有一点好转，任何模型都不会真正失败。","explanation":["原文定位：第2463—2478行；原文锚点 section-12-2；短引文：‘每条前瞻在输入截止后、结果出现前冻结’。本题源切片逐字附后，讲解与原文分开。","登记时间、输入截止与目标期限是三个不同角色。先关掉本次可用资料入口，再冻结判断，且不得已经看见目标结果。期限可以是窗口，输入截止不等目标开始；迟到证据可用于新版本，不回填旧运行。若目标结果已知，这份工作是回溯解释或回测，不能换名成前瞻登记。","前瞻ID与模型版本保证可追踪；目标、期限、对象和圈层范围决定到期究竟评谁、评什么；基线时点说明从哪里算变化。若原目标涉及全部团队，结果后缩到表现好的成员会改变合同，不能保留原成功资格。","目标要可判定，至少说明观察量、观察主体或来源、阈值和缺失处理。例如“关系变好”若使用某份量表，只能评价该测量合同下的变化，不等整段关系或每个人生活都好。目标定义应先检查是否真正对应任务，不能为了易计分而替换用户所关心的结果。","简单基线防止复杂故事自我胜利；候选机制与路径集合明确互斥、并行或不可比；概率、区间、等级或方向的表达强度与依据匹配。没有排序依据就写未知，不因必须登记而编数字。用于决策才填写相应决策阈值，否则可带理由不适用。","早期和反向信号是可辨路径的材料，暂停条件说明何时停止使用，退役条件说明何时退出该模型或变量；校准计划与结果回写则说明用什么真实标签、何时追加、按什么规则评价。单条预测得分不等长期校准，计划还须规定累积任务的同口径和不确定性处理。","原表七项最低问题分别针对模糊成功、无限等待、复杂度自证、事后挑支、伪精确、只寻支持和失败消失。它不是只要表格有内容就免于失败的凭证；字段中诚实的未知也可能表示当前还不具备发布前瞻资格。","子节12.2.1限定局部能力主张的对象、尺度、资源与表达；12.2.2要求递归按阶独立评价。父节负责登记入口，不能用一个总预测ID让不同阶次、不同人群或不同截止的结果混为一项。"],"distinctions":[{"leftTitle":"输入截止","leftText":"本次运行允许使用资料的最晚取得边界。","rightTitle":"结果期限","rightText":"目标在哪个时点或窗口接受判定。"},{"leftTitle":"基线时点","leftText":"计算变化的起始时刻。","rightTitle":"简单基线模型","rightText":"不用复杂结构的比较判断。"},{"leftTitle":"决策阈值","leftText":"用于指定行动复核的触发标准。","rightTitle":"概率或分类表达","rightText":"不自动成为执行许可，也不一定涉及决策。"},{"leftTitle":"登记完整","leftText":"可追踪与可失败条件明确。","rightTitle":"预测能力已证","rightText":"仍须结果、基线与适当评价。"}],"boundaries":["不得把结果后缩小成功子群算原目标命中。","窗口可取区间，但不能事后无限延长。","目标口径变化须新版本，未决不能填未发生。"],"questions":["09:00得到新信号能否回填08:00那条预测？","Ptoy01目标概率为什么是0.6？","盘点缺失时能否记标签0？"],"diagramPath":"/reading-assets/S-12-2/figures/section-12-2.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.2","start_line":2463,"end_line":2478,"startLine":2463,"endLine":2478}],"outputId":"section-12-2","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["在结果前冻结目标、期限、范围、输入截止、登记时间与版本。","定义发生/未发生/未决的可判规则，防止结果后改人群和阈值。","固定简单基线、机制路径、表达方式和适用的决策阈值。","预写正反信号、暂停退役、校准与追加回写计划。","资料不足时保留不能发布的缺口，不用空表或虚构参数代替。"],"teachingExamples":[{"title":"数学教学构造：一条完整前瞻登记","text":"ID=Ptoy01，模型v1；对象=虚构维修队列Q，圈层=本局部任务不使用圈层分组；基线08:00 B0=6；输入截止08:00，登记08:01；目标为10:00记录B≥8，期限是当日10:00盘点，标签在10:05核齐，若盘点缺失则未决。题设生成机制：两小时到件2/小时、处理率c在整个窗口恒定，c=1概率0.6、c=3概率0.4；因此终点8或4，目标概率0.6。简单基线p0=0.5为独立预设教学比较。路径两支互斥；校准计划为按同一生成机制累积任务并记录Brier及同概率组发生比例，不从单例认证校准；决策阈值不适用，因为只评价预测。早期信号=09:00同口径积压7或5；反向信号=与支不符的值或生成条件变化；暂停=输入口径或对象变化；退役=后续同合同检验长期不优于基线并经复核。回写=10:05后追加盘点来源、标签、损失及偏差；证据引用=本例公开题设Etoy，不冒充现实记录。","assumptions":"概率是人为规定的形式生成分布，不是从现实维修数据估得。所有时间、记录和校准计划均为构造，未实际开展重复任务。","boundary":"09:00新信号若用于更新，必须建立新冻结运行；Ptoy01仍按08:00信息评价。"},{"title":"教学构造：模糊目标改写需保留未决","text":"“团队关系变好”可在特定测量任务中改为“固定成员集合在预定两次时点的同一自愿测量，按预设计分和缺失规则，某指标变化达到阈值”。若成员退出或拒绝披露，不默认其改善或恶化；按事前规则登记缺失/未决并检查目标同一性。","assumptions":"这里只给设计原则，不制定真实心理测验或采集个人资料；阈值和量表未提供所以不赋值。","boundary":"一个指标不能代表全部关系、尊严或生活结果，现实采用须检验构念和保护。"}],"counterexamples":[{"identity":"constructed_boundary","text":"原来预测整个部门改善，结果后只看改善的小组也算成功。","effect":"对象范围被偷换，必须另建目标，旧记录继续。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"没有现实概率依据也应填0.5，才算中立。","effect":"0.5是概率主张，不由无知自动产生。","sourceIds":["theory"]}],"questionAnswers":[{"question":"09:00得到新信号能否回填08:00那条预测？","answer":"不能，可新建09:00运行，旧预测仍按原截止评价。","basis":"本节原文及上述公开推导"},{"question":"Ptoy01目标概率为什么是0.6？","answer":"在明确人为生成机制下，仅c=1支给8并满足B≥8，其题设概率0.6；不是现实估计。","basis":"本节原文及上述公开推导"},{"question":"盘点缺失时能否记标签0？","answer":"不能，按登记为未决，缺失不是未发生。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-2/figures/section-12-2.png","alt":"08:00输入截止，08:01登记Ptoy01，题设p=0.6；10:00目标盘点，B≥8记1，否则0，缺标签记未决；10:05后追加评价，保留原预测，新信号另开版本。全部为教学登记；时间与概率不是现实业务记录。","caption":"全部为教学登记；时间与概率不是现实业务记录。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。三栏为条件和评价责任，当前静态图未连接真实预测或结果系统。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节要求完整事前登记，所取得的历史事后评价报告不含本讲全部冻结字段。采用显式生成分布和完整构造，避免把事后报告冒称事前登记。"},"openQuestions":["本题没有现实预测登记或实验结果；若用于团队关系任务，还需合适测量、缺失规则与相应保护。"],"taskId":"S-12-2","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2463—2490行；每节精确范围见sourceRefs","claim_support":["12.2：术语、合同、论证责任和原文边界；不据此认证经验事实","12.2.1：术语、合同、论证责任和原文边界；不据此认证经验事实","12.2.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"met2024","title":"Tropical cyclone verification northern hemisphere 2024","url":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024","source_type":"primary","version_or_date":"2024季节报告","locator":"§3.3表，Possibly verified行T+24=125、T+168=15","claim_support":["12.2.1：不同提前量有不同可验证预报数，展示时间与观测边界"],"limits":["不是独立风暴数；未取得逐案资料，不估因果效应或当前准确率。"],"access_status":"partially_read"},{"id":"metdefinitions","title":"Tropical cyclone forecast verification - measures of error","url":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/appendix","source_type":"primary","version_or_date":"页面未标日期；2026-10-14读取","locator":"术语列表 Possibly verified 与 Detection rate 两项","claim_support":["Possibly verified是有验证观测的预报数量，与检测率分开"],"limits":["业务术语只在该报告口径下使用，不直接等同所有分类任务分母。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-2/lecture.md","sourcesPath":"/reading-assets/S-12-2/sources.json","sourceSlicePath":"/reading-assets/S-12-2/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-2/diagrams.md"},"12.2.1":{"title":"12.2.1　局部可预测性边界","lead":"不要只问“这个模型能预测吗”，要问：预测哪个对象、什么状态区域、多久以后、允许多大误差、用什么信息和资源。一个任务中的好表现，不是一张可用于所有未来的许可证。","explanation":["原文定位：第2479—2484行；原文锚点 section-12-2-1；短引文：‘不是一条每项任务都必须依次爬升的精度阶梯’。本题源切片逐字附后，讲解与原文分开。","局部可预测性至少绑定对象、状态区域、尺度圈层、时间窗、容差、可用信息、计算与观测资源、版本、基线、弃权与失效条件。某模型在正常负荷下一小时有效，不意味着在极端负荷或一年后同样有效；扩大边界要有新证据。","世界整体是否可预测超出本框架直接可检验范围。本节允许的是在具体任务内发现有限增量，既不因局部成功宣布全面预知，也不因长期未知否定所有短窗问题。有限能力可以真实存在，只是必须接受对应条件限制。","分类、等级、区间和概率有不同语义。分类关心类别判定，等级关心有依据的顺序，区间保留允许值域或明确覆盖合同，概率对应事件生成或经验估计。它们不是从低级到高级的统一阶梯，任务可以只需类别，概率也未必比正确的区间更适合用途。","选择表达要核目标、单位、生成方法、识别条件和校准状态。连方向都不识别时，应写未知而不是退为“至少判断趋势”。形式模型可以已知概率，但要明确由假设给定；经验概率须有现实数据与适用范围，不靠AI把稀疏文字补成参数。","借数学或物理理论须同时带原对象、假设、极限或尺度律、误差、有效域、对象映射、反例与退出条件。把社群称为流体、把信息称为能量，不使对应方程自动适用。可用比喻启发提问，若声称定量规律则必须给真实映射与验证。","资源边界也是能力的一部分。用后来才能取得的资料进行回测，不代表当时实时可预测；计算预算超出决策窗口，可能无法实际提供所称提前量。弃权则保留模型在不适用域不发布判断的能力，评价时应同时报告弃权范围，不能只展示愿意答的简单案例。"],"distinctions":[{"leftTitle":"有限任务增量","leftText":"在明示边界下优于基线。","rightTitle":"世界整体可预测","rightText":"并非由局部评价推出。"},{"leftTitle":"形式已知概率","leftText":"由公开模型或题设给定。","rightTitle":"经验概率","rightText":"须现实材料和校准，不能偷换。"},{"leftTitle":"方向判断","leftText":"需要可辨识的正负或顺序。","rightTitle":"没有概率时随便说趋势","rightText":"同样越过证据边界。"},{"leftTitle":"公式外形相似","leftText":"比喻或启发线索。","rightTitle":"定量映射成立","rightText":"需对象、单位、假设及经验支持。"}],"boundaries":["样本多不能修复测量口径错，样本少也不一概禁止有明确先验和模型的后验。","不同提前量可能对应不同可评价样本，不能只看误差大小断言同对象性能因果变化。","弃权不能被隐藏而使结果看似全域有效。"],"questions":["Δ可为−2或+3，为什么不能说大概上升？","误差2对容差3和1的任务结果是什么？"],"diagramPath":"/reading-assets/S-12-2/figures/section-12-2-1.png","caseLinks":[{"title":"2024年气旋检验：提前量伴随不同样本边界","href":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024"}],"caseNotes":[{"title":"2024年气旋检验：提前量伴随不同样本边界","text":"英国气象局该报告北大西洋表中，可供检验预报数在T+24为125，在T+168为15。这里新增观察点是期限扩大会改变可评价样本，不能把短窗能力无条件延伸到长窗。","sourceLabel":"Met Office，2024北半球检验报告","sourceUrl":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024","sourceLocator":"§3.3表，Possibly verified行，T+24与T+168列；定义见该报告链接的measures of error附页","boundary":"这些是有验证观测的预报数，不是独立风暴数；不同提前量的选择与检测条件须另核，不能由125与15估计因果效果。","href":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024"}],"sourceRefs":[{"section":"12.2.1","start_line":2479,"end_line":2484,"startLine":2479,"endLine":2484}],"outputId":"section-12-2-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["把可预测性主张限定到具体对象、状态区、时窗、容差和资源。","声明信息截止、版本、基线及弃权/失效条件。","按目标与证据选择表达类型，不把方向当无证据默认。","借用外部公式时核原假设与对象映射，说明误差和退出条件。","超边界结果降级或重新检验，不从局部向整体自动外推。"],"teachingExamples":[{"title":"数学构造：没有概率也可能没有方向","text":"设未来变化Δ由相容机制给出−2或+3，未有概率或选择机制证据。可以报告集合{−2,+3}，不能说“倾向上升”，也不能平均为0.5当现实预测。若新证据排除负支，才可在剩余模型内给正方向。","assumptions":"允许机制集合纯构造，不声称穷尽现实所有可能。","boundary":"条件集合与置信区间不同，未赋两支等概率。"},{"title":"数学构造：不同容差给不同任务资格","text":"虚构点预测10、实际值12，绝对误差2。若事前任务容差≤3，本例满足；若另一个任务容差≤1，本例不满足。不能把第一个任务成功迁移成第二个成功，也不能结果后把容差从1改3。","assumptions":"数值与容差是教学设定，不以单例证明长期能力。","boundary":"容差还须与真实用途和损害相称，不能为求好成绩随意放宽。"}],"counterexamples":[{"identity":"constructed_boundary","text":"模型能预测24小时，所以同一准确率适用于一周。","effect":"时间窗、状态域和可用信息变化，需分别验证。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"既然概率不足，至少方向总能判断。","effect":"相容机制可给相反方向，方向也可能未知。","sourceIds":["theory"]}],"questionAnswers":[{"question":"Δ可为−2或+3，为什么不能说大概上升？","answer":"未有概率或排除负支的证据；报告两方向及辨别材料。","basis":"本节原文及上述公开推导"},{"question":"误差2对容差3和1的任务结果是什么？","answer":"前者符合、后者不符；任务合同不同，不许事后换门槛。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-2/figures/section-12-2-1.png","alt":"对象与状态区域，尺度／时间窗／容差，信息与资源；匹配表达资格，分类／等级／区间／概率，方向亦可能未知；有限检验结果，基线／版本／弃权，越界则降级。各类型不是精度阶梯；同一局部结果不能覆盖全部未来。","caption":"各类型不是精度阶梯；同一局部结果不能覆盖全部未来。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。三栏为条件和评价责任，当前静态图未连接真实预测或结果系统。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"同一业务表实际按提前量报告不同样本规模，适合说明局部能力的时间与观测边界。"},"openQuestions":["未取得每条预报记录，不把各提前量汇总当相同独立样本试验；不外推当前模型能力。"],"taskId":"S-12-2","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2463—2490行；每节精确范围见sourceRefs","claim_support":["12.2：术语、合同、论证责任和原文边界；不据此认证经验事实","12.2.1：术语、合同、论证责任和原文边界；不据此认证经验事实","12.2.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"met2024","title":"Tropical cyclone verification northern hemisphere 2024","url":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024","source_type":"primary","version_or_date":"2024季节报告","locator":"§3.3表，Possibly verified行T+24=125、T+168=15","claim_support":["12.2.1：不同提前量有不同可验证预报数，展示时间与观测边界"],"limits":["不是独立风暴数；未取得逐案资料，不估因果效应或当前准确率。"],"access_status":"partially_read"},{"id":"metdefinitions","title":"Tropical cyclone forecast verification - measures of error","url":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/appendix","source_type":"primary","version_or_date":"页面未标日期；2026-10-14读取","locator":"术语列表 Possibly verified 与 Detection rate 两项","claim_support":["Possibly verified是有验证观测的预报数量，与检测率分开"],"limits":["业务术语只在该报告口径下使用，不直接等同所有分类任务分母。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-2/lecture.md","sourcesPath":"/reading-assets/S-12-2/sources.json","sourceSlicePath":"/reading-assets/S-12-2/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-2/diagrams.md"},"12.2.2":{"title":"12.2.2　递归前瞻的按阶评价","lead":"第一阶猜对、第三阶猜错，不能混成一个漂亮总分后说“递归有效”。每阶有不同问题和信息依赖，要分别冻结、分别与合理的浅层方法比较。","explanation":["原文定位：第2485—2490行；原文锚点 section-12-2-2；短引文：‘不能合成一个总命中率’。本题源切片逐字附后，讲解与原文分开。","第一、二、三阶分别登记对象、目标、期限、输入截止、表达与评价规则。若各阶预测不同目标，不能只把命中数相加形成一个不透明总率；若需要综合指标，必须另有事前定义和权重，并仍保留分阶表现，不能替代原合同。","每阶需与三类比较对象对照：不继续递归的状态延续；直接对同一远期目标作判断；更浅阶次再加简单延续。这些比较用来区分“真的需要再入结构”与“只是时间往后走了”。不能把第二阶对困难远期目标的误差直接同第一阶容易短期目标比，再宣布递归有害或有益。","公平比较应匹配目标、期限、可用信息、评价规则，并合理说明计算和调参机会。额外证据、更多计算或更丰富结构各可能带来增益，须尽量辨开；简单基线不必被人为做得与复杂系统一样大，也不应故意不给它可用信息。","没有新外部材料时，全部子运行的证据谱系仍回到同一冻结起点。后处理可以发现原先没推出来的逻辑后果，揭示敏感性或隐蔽条件，这是真实的推理增量；但不能因此说多了一个现实样本或独立证据源。","真实中间结果到来后，应另建新截止运行。可以比较“原始起点一次推到底”与“利用后来实况更新”的表现，但后者用了更多资料，不能把提高全部归功于递归方法，更不能倒灌旧路径把它改成始终正确。","若三阶只增加故事而没有稳定样本外增量，保留为探索情景即可，不授予前瞻能力资格。一次表现更好或更差都不足以证明普遍规律；需按已登记用途和独立评价范围判断稳定性，必要时限定适用窗或退役。"],"distinctions":[{"leftTitle":"按阶评价","leftText":"每阶自身任务与合理对照分别评分。","rightTitle":"总体命中率","rightText":"可能遮蔽任务难度、期限和失败差异。"},{"leftTitle":"内部推理增量","leftText":"发现原输入蕴含的后果。","rightTitle":"外部证据增量","rightText":"出现新的现实材料，身份不同。"},{"leftTitle":"实况更新预测","leftText":"使用新截止后重估。","rightTitle":"原始递归预测","rightText":"仅用旧起点，一直按旧合同保留。"},{"leftTitle":"直接远期比较","leftText":"同目标下不经再入的预测。","rightTitle":"第一阶短期分数","rightText":"任务不同，不能直接判方法高低。"}],"boundaries":["不将重生成的子文本计为多个独立样本。","样本外评价也要防目标、时间与来源泄漏。","探索情景可以有用，即使前瞻增益尚未获得支持。"],"questions":["第三阶14、直接11、延续12、浅阶延续10，标签10，误差依次多少？","新中间实况带来的改善能全归于递归结构吗？","后处理没有新观察，是否完全没有价值？"],"diagramPath":"/reading-assets/S-12-2/figures/section-12-2-2.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.2.2","start_line":2485,"end_line":2490,"startLine":2485,"endLine":2490}],"outputId":"section-12-2-2","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["为每阶分别冻结目标、时窗、信息与评分合同。","用同目标对照状态延续、直接远期判断和浅阶加延续。","区分信息、计算和结构差异，保留分阶成绩。","子运行没有新外部材料时不增加现实证据计数。","中间实况另建新运行，无法稳定增益则降级为探索情景。"],"teachingExamples":[{"title":"数学构造：同目标下递归未赢基线","text":"虚构第三阶目标为第3小时队列值，真实标签10；递归预测14、直接远期预测11、当前状态延续12、浅阶加延续10。事前评分为绝对误差，则分别4、1、2、0。这个实例不支持递归优势；不能拿第一阶另一个短期任务恰好命中来抵销第三阶误差。","assumptions":"四预测、标签和规则都是教学构造，无真实实验；各比较都针对同一第3小时目标。","boundary":"一次样本不足以证明所有递归方法更差，只给出当前实例有限比较。"},{"title":"教学构造：新实况不能倒灌旧阶","text":"虚构08:00冻结三阶预测；09:00取得新盘点。以09:00盘点建立新运行并改善10:00预测，可以报告更新后结果，但08:00原预测仍保留。若把09:00数值写回旧第一阶，再重算旧第二、三阶并称“08:00已预测”，就发生信息泄漏。","assumptions":"时间和数据流程均为构造，未运行真实预测系统。","boundary":"更新有价值不意味着旧运行没价值；两种信息集应分别评价。"}],"counterexamples":[{"identity":"constructed_boundary","text":"同一起点生成100个子运行，相当于100份独立观察。","effect":"来源谱系相同，增加计算不增加现实样本。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"第一阶准确、第三阶不准，平均一下就证明三阶整体有效。","effect":"各阶任务与期限不同，应保留分阶和同目标对照。","sourceIds":["theory"]}],"questionAnswers":[{"question":"第三阶14、直接11、延续12、浅阶延续10，标签10，误差依次多少？","answer":"4、1、2、0；本例递归不占优，但不作长期普遍判断。","basis":"本节原文及上述公开推导"},{"question":"新中间实况带来的改善能全归于递归结构吗？","answer":"不能，它增加了信息；须新版本并区分信息与结构贡献。","basis":"本节原文及上述公开推导"},{"question":"后处理没有新观察，是否完全没有价值？","answer":"有可能增加推理、敏感性和条件理解，但不是现实证据自增长。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-2/figures/section-12-2-2.png","alt":"教学目标标签10，第三阶预测14，绝对误差4；直接远期预测11，绝对误差1；状态延续预测12，绝对误差2；浅阶加延续10，绝对误差0；每阶单独登记，不混短期命中，不隐藏第三阶失败；新实况另开版本，原信息集不回填，推理≠新观察。数字为教学构造；同目标比较仅一个实例，不认证长期方法优劣。","caption":"数字为教学构造；同目标比较仅一个实例，不认证长期方法优劣。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。四个方法卡并列，不用曲线伪造实验走势；后两卡提示信息边界。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节规定分阶比较与信息谱系，当前没有真实三阶冻结预测及独立标签档案；采用同目标可复算评分，避免虚构递归前瞻实验。"},"openQuestions":["稳定样本外增益需要真实分阶记录与同目标对照，本题未实施。"],"taskId":"S-12-2","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2463—2490行；每节精确范围见sourceRefs","claim_support":["12.2：术语、合同、论证责任和原文边界；不据此认证经验事实","12.2.1：术语、合同、论证责任和原文边界；不据此认证经验事实","12.2.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"met2024","title":"Tropical cyclone verification northern hemisphere 2024","url":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024","source_type":"primary","version_or_date":"2024季节报告","locator":"§3.3表，Possibly verified行T+24=125、T+168=15","claim_support":["12.2.1：不同提前量有不同可验证预报数，展示时间与观测边界"],"limits":["不是独立风暴数；未取得逐案资料，不估因果效应或当前准确率。"],"access_status":"partially_read"},{"id":"metdefinitions","title":"Tropical cyclone forecast verification - measures of error","url":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/appendix","source_type":"primary","version_or_date":"页面未标日期；2026-10-14读取","locator":"术语列表 Possibly verified 与 Detection rate 两项","claim_support":["Possibly verified是有验证观测的预报数量，与检测率分开"],"limits":["业务术语只在该报告口径下使用，不直接等同所有分类任务分母。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-2/lecture.md","sourcesPath":"/reading-assets/S-12-2/sources.json","sourceSlicePath":"/reading-assets/S-12-2/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-2/diagrams.md"},"12.3":{"title":"12.3　简单基线与增量能力","lead":"复杂模型要回答一个朴素问题：同样的信息、同样的目标和截止，如果用更简单的方法会怎样？故事更丰富、图更多或变量更多，都不能替代这场比较。","explanation":["原文定位：第2491—2498行；原文锚点 section-12-3；短引文：‘应优先简单模型’。本题源切片逐字附后，讲解与原文分开。","增量能力是相对任务适配基线的差异，不是模型独自报一个好看的误差。基线可以延续趋势、沿用最近状态、使用历史频率、只用行动者状态、只用主圈层状态，或采用领域已有成熟方法。选择应符合数据和任务，不故意选明显不适用的弱对手。","公平比较首先要求同信息、同截止、同目标、同期限和同评价规则。若复杂模型拿到后来发生的事件，简单模型只能用更早资料，差异不能被归为多圈层结构的贡献。若复杂模型只在容易样本评分而基线在全体评分，也不是同一比较。","材料、推理预算和调参机会尽量相称，不是强迫简单基线也长成复杂模型。应分别说明增加信息、增加计算与增加结构假设带来什么；可以用受限对照或消融设计，但不要只凭一个总分就完成因果归因。未能隔离贡献时如实标明。","预测系统通常需要独立测试或样本外复核，且要防时间、对象或来源泄漏。对于时间序列，未来资料不能进入过去预测输入，相关记录也不宜当完全独立样本。没有可用测试时保留能力未证实，不能把训练拟合或事后解释算作前瞻成绩。","解释增益与预测增益分开。一个模型可能使机制、承担位置或约束更清楚，但预测并不优于基线；若解释增益本身有相应材料，可保留它，同时写前瞻增益未获支持。解释是否真正变好也需标准，不能仅因篇幅变长就自封。","复杂度有缺失、误测、隐私、过拟合与维护成本。采更多人的资料会增加风险，模型版本也需持续维护。若只在少量状态域有效，应限制使用；若增益衰退，降级或退役；若表现相同而无其他足够理由，优先简单模型，避免为术语规模付无谓成本。","相同表现是对当前比较的有限结论，不一定证明总体统计等价。一次简单方法赢，不证明复杂方法永远差；反过来，一次复杂方法赢也不支持普遍优势。最终报告应交代样本、误差不确定性、适用域、调参机会和成本，而不是只交冠军名称。"],"distinctions":[{"leftTitle":"解释增益","leftText":"对机制或约束的有证据理解改善。","rightTitle":"前瞻增益","rightText":"对未见结果的同合同表现更好。"},{"leftTitle":"公平计算条件","leftText":"预算和调参机会可比较且差异透明。","rightTitle":"基线等大","rightText":"不要求简单方法膨胀成同规模。"},{"leftTitle":"增添信息","leftText":"输入更丰富或更新。","rightTitle":"结构增量","rightText":"在相应信息条件下由表示和机制带来的差异。"},{"leftTitle":"训练拟合","leftText":"解释已用于调参的记录。","rightTitle":"样本外表现","rightText":"对未用于选择模型的资料评价，仍须防泄漏。"},{"leftTitle":"相对基线技能","leftText":"某损失相对比较对象改善。","rightTitle":"事件发生概率或命中率","rightText":"不同量，百分号也不能互换。"}],"boundaries":["没有独立测试不能把能力当已证，也不能编造测试结果。","基线不能故意不给它可用资料，复杂模型也不应获取未来标签。","跨域外推需复核，单域样本外优势不等全域胜出。","复杂度相同不是公平的唯一标准，实际维护和保护成本也要看。"],"questions":["示例两方法MAE是多少，能下多强结论？","如何区分增加信息与增加结构？","复杂方法只改善解释怎么办？"],"diagramPath":"/reading-assets/S-12-3/figures/section-12-3.png","caseLinks":[{"title":"2024年北大西洋检验：技能要有比较对象","href":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024"}],"caseNotes":[{"title":"2024年北大西洋检验：技能要有比较对象","text":"英国气象局报告北大西洋T+24小时Track skill为68%；官方误差定义说明，该量比较模型位置预报与CLIPER气候—持续性基线，正值表示模型误差更低。本节新增观察点是68%不是事件概率或逐案命中率。","sourceLabel":"Met Office，2024检验报告与误差定义","sourceUrl":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024","sourceLocator":"§3.3表Track skill(%)行T+24列；定义附页术语列表Track skill及Sign conventions同名项","boundary":"只复述报告的相对指标及定义，不从四舍五入汇总反算精确基线误差，不推断所有风暴表现或长期普遍优势。定义来源同时见sources中的metdefinitions。","href":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024"}],"sourceRefs":[{"section":"12.3","start_line":2491,"end_line":2498,"startLine":2491,"endLine":2498}],"outputId":"section-12-3","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["选择任务适配的简单或领域基线，先冻结比较合同。","让各方法接受同目标、信息截止、期限、样本及评分。","合理配平计算与调参，并区分信息、计算和结构贡献。","用独立或样本外材料检验，缺少则保留能力未证。","按增益与代价限制适用域，增益消失时降级；同等表现优先简单。"],"teachingExamples":[{"title":"数学构造：同目标平均误差比较","text":"虚构独立测试标签y=(10,12,8)，复杂模型预测(9,13,9)，简单模型预测(10,10,10)。按事前平均绝对误差，复杂模型为(1+1+1)/3=1，简单模型为(0+2+2)/3=4/3。该测试集上复杂方法平均误差少1/3；若另有采集成本，净选择仍需规范比较，不能只凭这三个样本宣称稳定全域优势。","assumptions":"全部数据与独立身份为教学设定，没有执行真实测试。","boundary":"误差改善只对这个样本和指标成立，不替置信区间或长期增益检验。"},{"title":"数学构造：技能百分比不是命中率","text":"某教学任务基线平均损失10、模型平均损失8，定义相对技能S=1−L模型/L基线，则S=1−8/10=0.2即20%。它表示本例损失较基线少20%，不表示事件发生概率20%，也不表示80%或20%的预测逐项命中。","assumptions":"损失单位一致、基线非零，技能定义为本例公开规则。","boundary":"不同领域可能使用不同技能分数，不能把此公式强贴所有报告。"},{"title":"教学构造：后来信息造成不公平胜出","text":"虚构甲在08:00预测10:00库存，只用08:00资料；乙到09:30已看到大部分入库后预测同目标，误差更小。可以说乙利用更多信息做了更晚预测，不能说乙的结构模型在同截止下更强。需要按同08:00或同09:30资料分别比较。","assumptions":"时间、信息和成绩仅为教学场景，没有真实业务数据。","boundary":"更晚更新可能很有用，但其剩余提前量、决策窗口和信息成本须另评。"}],"counterexamples":[{"identity":"constructed_boundary","text":"复杂模型图更全，所以即使误差相同也证明前瞻能力提高。","effect":"结构丰富不是预测增益，需要同合同结果比较。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"基线只用旧资料、复杂方法用了新资料，差异全来自结构。","effect":"信息贡献混入，不能单独归因。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"相对基线技能20%，所以20%的事件会发生。","effect":"损失相对量不是事件概率。","sourceIds":["theory"]}],"questionAnswers":[{"question":"示例两方法MAE是多少，能下多强结论？","answer":"1与4/3，本测试集复杂方法少1/3；三个构造样本不证明稳定优势。","basis":"本节原文及上述公开推导"},{"question":"如何区分增加信息与增加结构？","answer":"按同信息条件设置对照，并公开预算与调参差异；无法隔离则不作单一贡献归因。","basis":"本节原文及上述公开推导"},{"question":"复杂方法只改善解释怎么办？","answer":"保留有材料的解释增益，明确前瞻增益未支持，按用途和成本决定是否继续使用。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-3/figures/section-12-3.png","alt":"同目标／期限，同信息／截止，同样本／评分；任务适配基线，最近状态／趋势，历史频率／领域方法；复杂模型，额外信息、计算、结构，分别说明贡献；教学测试标签，10、12、8，非真实实验；简单预测10、10、10，MAE=4/3；复杂预测9、13、9，MAE=1，本样本少1/3。数字为教学构造；一次样本比较不证明稳定全域优势。","caption":"数字为教学构造；一次样本比较不证明稳定全域优势。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。上下两排分别为比较合同与可复算示例，不将节点数量转为能力分数。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"该一手业务体系实际以CLIPER作技能基线，直接说明比较对象与性能指标的语义。"},"openQuestions":["未获得逐案误差与模型调参记录，不作统计显著性或结构贡献估计。"],"taskId":"S-12-3","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2491—2498行；每节精确范围见sourceRefs","claim_support":["12.3：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"met2024","title":"Tropical cyclone verification northern hemisphere 2024","url":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/nhem2024","source_type":"primary","version_or_date":"2024季节报告","locator":"§3.3表Track skill(%)，T+24=68","claim_support":["2024北大西洋24小时相对技能报告值为68%"],"limits":["不是发生概率或命中率；未独立复算逐案误差，不从舍入数反推精确基线。"],"access_status":"partially_read"},{"id":"metdefinitions","title":"Tropical cyclone forecast verification - measures of error","url":"https://www.metoffice.gov.uk/research/weather/tropical-cyclones/verification/summaries/appendix","source_type":"primary","version_or_date":"页面无独立日期；2026-10-14读取","locator":"术语列表Track skill；Sign conventions中Track skill positive…","claim_support":["Track skill以CLIPER为位置比较基线；正值表示模型误差低于CLIPER"],"limits":["只解释此业务指标，不把百分比当概率，也不外推当前服务表现。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-3/lecture.md","sourcesPath":"/reading-assets/S-12-3/sources.json","sourceSlicePath":"/reading-assets/S-12-3/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-3/diagrams.md"},"12.4":{"title":"12.4　概率、等级与时间窗","lead":"概率、值得先看、个人相信和价值上更重要，都可能用数字表达，但不是同一个量。说清数字在回答哪个问题，比把它写得精细更重要。","explanation":["原文定位：第2499—2517行；原文锚点 section-12-4；短引文：‘不能为排序需要编造百分比’。本题源切片逐字附后，讲解与原文分开。","概率或概率区间要对应可判定事件，并说明生成模型、适用时的先验、数据、边界与校准状态。概率依据不足时，可以给有证据的等级或路径比较；但排序也可能未知，不能将“缺概率”自动处理为“至少能给方向”。样本大小只是条件之一，不独自决定输出类型。","原表四种证据状态对应不同上限：有概率依据则可给概率；仅有等级依据则保留不可比项与反向信号；方向有识别依据才给方向，否则给未知及最小辨别观察；目标或对象不稳定时不发布前瞻，应先重新定义合同。它们不是强制依次降级的等级链。","时间窗随机制时钟，短期情绪反应、组织流程和制度改动不能共用一个默认期限。把慢机制塞进短窗，会在还没到可能生效时误判无效；把短期信号无限延长，也会把暂态当趋势。多时钟任务可分别登记中间结果和最终结果期限，并保持各自评价。","现实概率讨论事件在相应条件下的发生可能，须有估计或校准依据；主观信念记录某行动者在特定信息下的判断；决策权重来自描述模型或价值前提；路径排序只在相应比较关系下成立；计算优先级说明有限资源先研究什么。这五类即使用相同0.8，也不能互相证明。","高后果、窗口短或容易区分，可以使一条概率未知路径获得高检查优先级。公开优先理由与预算即可，不必为显得理性编一个百分比。最值得检查不等最可能发生，最希望发生也不等最可能发生；推荐排序还需规范与分配，不能由发生概率直接推出。","模型抽样频率只是在给定参数、采样方法和规则下的计算结果。它可以估计模型条件概率，但与现实概率之间还需映射、参数支持及校准；多抽几次不能弥补模型错或未观测变量。若抽样设计主动过采某风险支，频率甚至不等该模型原分布下的概率，必须保留权重与方法。","小样本在明确先验和似然下可以产生后验，但后验仍依赖那些假设，不能宣称小样本本身足以认证现实参数。大量样本也可能共享错误口径或选择偏差，精确估计一个错的量不等得到所问事件的概率。","概率判断、经验校准和规范优先级应分别发布。一个人确信度高不是长期频率已校准；在可比任务中校准良好也不自动满足各子群保护或行动授权。表达强度由证据和用途支撑，不由读者希望的确定性或模型流畅程度决定。"],"distinctions":[{"leftTitle":"现实概率","leftText":"针对目标事件、条件和估计依据。","rightTitle":"个人信念","rightText":"某人在某信息下的判断，不自动经验校准。"},{"leftTitle":"研究优先级","leftText":"受后果、时间窗、可区分性与预算影响。","rightTitle":"发生概率排序","rightText":"需要相应事件概率证据。"},{"leftTitle":"模型条件频率","leftText":"由给定规则和抽样设计产生。","rightTitle":"现实发生频率","rightText":"须有外部资料及可迁移条件。"},{"leftTitle":"后验概率","leftText":"先验与似然下的数据更新。","rightTitle":"无假设的客观真值","rightText":"不存在从算式自动消除模型条件的跳跃。"},{"leftTitle":"定性方向","leftText":"也是需识别支持的结论。","rightTitle":"默认保底答案","rightText":"证据可同时容许相反方向。"}],"boundaries":["对象不稳定时不发布旧合同前瞻，不能用模糊目标隐藏失败。","抽样数量大只可能降低相应计算误差，不能把模型输出升级成现实。","优先检查高后果支不等已知它很可能，也不等有权实施高影响行动。","同一概率对不同承担位置的决策含义可能不同，价值分配另论。"],"questions":["均匀先验、一次成功，后验预测为何为2/3？","为检查A而生成一半A，能否说A概率一半？","概率未知能否先查某支？","短期信号为何不能无限延长为趋势？"],"diagramPath":"/reading-assets/S-12-4/figures/section-12-4.png","caseLinks":[{"title":"2020年论文中的模拟分布：真实数据入口不等真实响应过程","href":"https://proceedings.mlr.press/v119/perdomo20a/perdomo20a.pdf"}],"caseNotes":[{"title":"2020年论文中的模拟分布：真实数据入口不等真实响应过程","text":"Perdomo等的原论文将§5.2明确标为模拟：基础使用真实信用数据子集，但行动者响应与分布变化按模型设定。本节只借这项实际发表的研究设计说明，真实数据和模拟机制可以并存，后者仍须保留假设身份。","sourceLabel":"Perdomo、Zrnic、Mendler-Dünner、Hardt，2020","sourceUrl":"https://proceedings.mlr.press/v119/perdomo20a/perdomo20a.pdf","sourceLocator":"PDF第2页§1.1末段“semi-synthetic”；第8页§5.2 Simulations前三段及Figure2采样程序","boundary":"这是论文真实采用的研究方法，不是真实借款人被实验性部署后的行为结果。未复现代码、未接触个人数据，也不提供信用决策建议。","href":"https://proceedings.mlr.press/v119/perdomo20a/perdomo20a.pdf"}],"sourceRefs":[{"section":"12.4","start_line":2499,"end_line":2517,"startLine":2499,"endLine":2517}],"outputId":"section-12-4","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["为每个数字或等级指定对象：事件概率、信念、权重、排序还是研究优先级。","按目标稳定性、生成方法和识别条件选择表达，缺方向依据则保留未知。","为各机制结果设置相应时间窗，不无限外推短期信号。","区分模型抽样与现实概率，说明先验、数据、选择和校准边界。","高风险检查可先行排序但不编概率，行动推荐另作规范比较。"],"teachingExamples":[{"title":"数学构造：一条数据也能有条件后验","text":"未知成功率θ∈[0,1]，人为规定均匀先验密度1，试验条件独立同分布且一次观察为成功，似然为θ。归一化常数∫0到1 θdθ=1/2，故后验密度2θ，下一次成功的后验预测均值∫0到1 θ·2θdθ=2/3。计算成立依赖先验、观测与生成假设，不是“看一次就知道现实成功率2/3”。","assumptions":"全为数学构造，只有模型内一次成功；没有真实试验和现实先验论证。","boundary":"换先验、选择性观察或非同分布会改变答案，不能以小样本或公式本身宣称现实校准。"},{"title":"教学构造：严重程度决定检查优先，不赋概率","text":"虚构系统有路径A可能导致不可逆损害且应对窗口10分钟，路径B只造成可回滚延迟且可等待一天。两者概率均未知，但按明示保护目标与当前核验资源，可以先检查A。报告应写“因后果与窗口优先核A，概率未知”，而不是为排序编“A有80%”。","assumptions":"风险类型、窗口与资源为构造，不描述真实紧急事件，也不授权实施动作。","boundary":"检查本身仍要有权限和安全边界；严重后果不是无条件行动借口。"},{"title":"数学构造：过采频率不是原模型概率","text":"虚构模型规定事件A概率0.1、非A概率0.9。为了检查A的后果，研究者刻意生成50个A场景和50个非A场景。样本中A占50%反映设计配额，不应报告模型概率变成0.5，更不应当现实概率。若要估原模型某期望，需要按原权重0.1与0.9合成各支条件结果。","assumptions":"概率与配额均由题设给定，未进行实际抽样；这里只展示设计分布与目标分布之别。","boundary":"实际重要性抽样还须满足相应支持和权重条件，本例不替完整估计程序。"}],"counterexamples":[{"identity":"constructed_boundary","text":"一百次生成中八十次出现某结局，所以现实概率80%。","effect":"必须知道生成分布、参数依据和现实映射，生成频率本身不足。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"样本只有一条，因此在任何明确概率模型下也不能给后验。","effect":"本构造给2/3但严格依赖先验与模型，小样本不单独决定是否可计算。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"最值得检查的路径必然最可能。","effect":"后果、窗口和辨别价值可改变优先级，不能混作概率。","sourceIds":["theory"]}],"questionAnswers":[{"question":"均匀先验、一次成功，后验预测为何为2/3？","answer":"密度从1按似然θ更新为2θ，积分θ·2θ得到2/3，前提都是公开模型假设。","basis":"本节原文及上述公开推导"},{"question":"为检查A而生成一半A，能否说A概率一半？","answer":"不能，那是采样设计配额；原模型给0.1，现实还需外部支持。","basis":"本节原文及上述公开推导"},{"question":"概率未知能否先查某支？","answer":"可以按明确后果、窗口和信息价值排序，保留概率未知与检查权限边界。","basis":"本节原文及上述公开推导"},{"question":"短期信号为何不能无限延长为趋势？","answer":"机制可能改变、慢变量及外部条件未被短窗支持，要分时窗登记和校准。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-4/figures/section-12-4.png","alt":"事件概率，目标／条件／数据，校准另核；个人信念，谁在什么信息下，如何判断；规范与研究优先，后果／窗口／预算，不必已知概率；教学模型P(A)=0.1，为检查刻意过采；生成50A＋50非A，样本A占50%；设计频率≠原概率，更不等现实概率，原权重仍0.1/0.9。下排为数学构造；上排三种量不能互换，数字相同也不表示语义相同。","caption":"下排为数学构造；上排三种量不能互换，数字相同也不表示语义相同。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。不画虚构概率曲线；未来交互切换采样配额时必须保留目标分布与实际分布标签。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"一手论文直接声明半合成设置与建模的分布映射，适合说明样本入口与生成机制的证据身份不能混同。"},"openQuestions":["本文未复现论文实验，也不把其理论稳定性或模拟结果外推为现实人群效应。"],"taskId":"S-12-4","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2499—2517行；每节精确范围见sourceRefs","claim_support":["12.4：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"perdomo2020","title":"Performative Prediction","url":"https://proceedings.mlr.press/v119/perdomo20a/perdomo20a.pdf","source_type":"primary","version_or_date":"ICML2020，PMLR119:7599—7609","locator":"PDF第2页§1.1末段；第8页§5.2 Simulations及Figure2","claim_support":["作者说明基础真实数据、分布映射建模的半合成设置，区分实际研究设计与真实部署效果"],"limits":["只读取相关方法段及理论定义，未完整复现实验或证明；不能当现实信用风险估计或授权依据。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-12-4/lecture.md","sourcesPath":"/reading-assets/S-12-4/sources.json","sourceSlicePath":"/reading-assets/S-12-4/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-4/diagrams.md"},"12.5":{"title":"12.5　校准与评价","lead":"评价先回答“在什么人群、响应制度和期限里，评什么”。分数能回答一个明确的预测问题，却不能顺带回答行动挽救了多少结果或谁有权行动。","explanation":["原文定位：第2518—2546行；原文锚点 section-12-5；短引文：‘缺失标签不填零’。本题源切片逐字附后，讲解与原文分开。","前瞻能力来自事先登记、获得同口径结果和持续比较，不来自事后解释听起来顺畅。原目标、期限、成功规则与信息截止必须冻结；单案可以得分，但不能由一案认证长期校准。结果资料的形成方式、缺失及对象进入退出也属于评价条件。","指标随任务而定：概率预测可用Brier分数、对数损失、校准曲线与分辨率；预测区间还看覆盖和宽度。排序用预先规定的排序指标，事件检测用精确率、召回率或相称领域指标，时间预测用窗口覆盖和提前量。不能因某项数值漂亮而换掉原来真正关心的目标。","二元Brier在本讲采用单事件约定L=(p−y)²，越低越好；对数损失采用自然对数，L=−[y ln p+(1−y)ln(1−p)]，概率0或1遇到相反标签时产生无穷损失。原始多类别向量式与这个二元单事件约定可能有常数倍差异，跨报告先统一定义。概率缺乏依据时，不应只为使用指标而编造概率。","校准问长期同类概率与观察比例是否对应；分辨率问是否能区分风险不同的对象。所有对象都报同一个总体发生率可能总体校准，却没有分辨能力。有限样本中某些分箱恰好匹配，也不能证明以后长期校准；还需样本量、不确定性、分箱方式与适用域。","原文六个评价维度各有修正方向。校准失效可调整表达或降级概率；分辨率不足可删无贡献变量或回基线；覆盖不足可修正区间或机制时钟；复杂模型无基线增益则停止其增益声明；跨时间地点不稳则限定域或退役；特定位置反复低估、误报则让受影响者复核并补救、升级保护。扩大区间虽可提高覆盖，却可能失去用途，不能只追一项数值。","用途决定错误成本和必要报告。提醒观察与强制措施即使共用分数，误报的负担也不同；低概率高损害任务不能只报总体准确率。须按承担位置、人群和阶段展示错误，不让总体平均掩盖某些人长期承受误拒、时延或漏报。指标优秀不等解释机制正确，也不产生规范正当性。","发布预测会影响行动，行动可能改变实际事件；因此要写明响应制度。保留触达、实际执行、对象进入退出、资料形成及制度变化记录。对于在现行响应制度下定义的实际事件目标，仍按其真实标签评分；不能用“模型影响了现实”取消本来合法的得分，也不能把所有预测评价强制改造成干预效果研究。","三个入口并行而不互相替代：第一，冻结目标下的预测表现，用同口径标签算损失、分类或覆盖；第二，发布或行动改变了多少结果，需要相称因果比较；第三，预测和响应是否合宜，需要明示规范、保护、成本、分配与权限。没有观察到事件，单独看这句话既不证明误报也不证明保护成功，要回到目标、标签与响应定义。","具体地，若事前目标正是在现行响应制度下的实际事件，登记p=0.8、到期完整y=0，则Brier=0.64；如事前阈值0.5，也可登记这个目标的假阳性。这个计算不告诉我们无行动时会怎样。若监测离线，y未知，就不能代入0；已接受服务者的完整标签也只直接支持该群体，不能替未触达、被拒或退出者填标签。","制度改变后先判断问题是否仍同一个。目标未变就诚实报告性能变化及可比性限制；目标改为另一个响应制度或人群则另立登记，保留旧预测与旧得分。不可事后将“现行制度下会发生”改成“若没有响应便会发生”来救援错误预测。"],"distinctions":[{"leftTitle":"单案损失","leftText":"对一次冻结预测与完整标签计算。","rightTitle":"长期校准","rightText":"同类预测的长期概率和发生比例是否匹配。"},{"leftTitle":"校准","leftText":"概率频率对应程度。","rightTitle":"分辨率","rightText":"能否分开风险不同的对象。"},{"leftTitle":"预测评价","leftText":"现行响应制度下目标的表现。","rightTitle":"干预效果","rightText":"实际响应相对于适当比较条件改变多少。"},{"leftTitle":"完整标签为零","leftText":"按定义确认事件未发生。","rightTitle":"未取得标签","rightText":"可能监测离线或选择性不可见，不能填零。"},{"leftTitle":"适用域内优秀","leftText":"指定人群目标制度上的表现。","rightTitle":"可推广且正当","rightText":"还需迁移、分配、规范和权限论证。"}],"boundaries":["反身性不豁免已经明确定义且有完整标签的评分。","观察到无事件不能单独识别保护成功；观察到事件也不单独说明一切响应无效。","总体校准不保证子群校准，更不自动满足公平或保护约束。","分数证明的只是相应预测性能，不能证明原因正确、行动有权或没有遗漏人群。"],"questions":["p=0.8、y=0为什么损失0.64而不是0.2？","无事件可同时兼容哪两种因果情况？","模型总体报0.5并有一半事件，是否说明分辨率好？","响应制度改变是否必须丢弃旧评分？","标签缺失能否按保守方式记零？"],"diagramPath":"/reading-assets/S-12-5/figures/section-12-5.png","caseLinks":[{"title":"研究案例：将预测引起的分布变化纳入评价对象","href":"https://proceedings.mlr.press/v119/perdomo20a/perdomo20a.pdf"}],"caseNotes":[{"title":"研究案例：将预测引起的分布变化纳入评价对象","text":"Perdomo等在2020年论文开篇讨论预测被用于决策后可能改变所预测的结果，并以依赖模型参数的分布D(θ)形式化其问题。这是一项实际发表的理论建模工作，为明确响应制度提供方法线索；不是证明任一具体预警已经挽救结果。","sourceLabel":"Perdomo等，2020，Performative Prediction","sourceUrl":"https://proceedings.mlr.press/v119/perdomo20a/perdomo20a.pdf","sourceLocator":"PDF第1页Abstract与§1首两段；第3页§2.1","boundary":"这里只使用问题设定与定义，不移植其优化结论，也不把论文当作某现实干预的效果证据。","href":"https://proceedings.mlr.press/v119/perdomo20a/perdomo20a.pdf"}],"sourceRefs":[{"section":"12.5","start_line":2518,"end_line":2546,"startLine":2518,"endLine":2546}],"outputId":"section-12-5","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["冻结目标、人群、期限、信息截止、评分约定及响应制度。","按实际用途选择指标，并把同口径标签、缺失和形成过程登记清楚。","对原预测计算合法分数；缺失标签不按未发生处理。","另外识别发布或行动的因果效果，不拿无事件单独证明避免成功。","另以规范、保护、分配和权限比较采用方案，不能让分数代签授权。","按六维评价调整适用域与输出强度，改变目标则新登记并保留旧结果。"],"teachingExamples":[{"title":"数学构造：Brier为何在固定生成模型内偏好真实概率","text":"规定Y为参数q的Bernoulli变量，预测为p。期望损失q(1−p)²+(1−q)p²=p²−2pq+q=(p−q)²+q(1−q)。后一项与p无关，前项非负且仅p=q为零，所以期望在p=q最小。这是给定生成模型内的代数证明，不等于从某次低得分反推出模型参数真实。","assumptions":"固定同一目标与分布，p,q∈[0,1]；仅数学推导，无真实试验。","boundary":"制度变化、选择性标签或目标不一致时不能直接套用同一个q；该性质不认证因果解释和行动权限。"},{"title":"数学构造：同样分箱校准，分辨率仍可不同","text":"构造20项完整标签：低风险组10项中2项为1，高风险组10项中8项为1。模型分别报0.2、0.8。每组Brier和均为2×0.8²+8×0.2²=1.6，总均值3.2/20=0.16。基线所有项报0.5，20项总体10次事件，整体比例与0.5相符，但每项损失0.25、无风险区分。此有限构造只展示分箱频率与分辨的差别。","assumptions":"标签、分组和概率均人为指定，没有真实拟合、校准样本或独立检验。","boundary":"恰好匹配20项不等长期校准；比较须预定分组且不能用评估标签反向挑选模型。"},{"title":"教学构造：能算0.64，不能算避免了多少","text":"虚构预警合同明确预测现行响应制度下的事件，登记p=0.8，阈值0.5，期末完整标签y=0。Brier=(0.8−0)²=0.64，对数损失−ln0.2约1.609，按阈值预测阳性而真实阴性，可记该目标的假阳性。若行动已发生且观察Y(行动)=0，另一条件Y(无行动)可能0也可能1：前者未改变是否发生，后者避免一次事件。当前观察无法区分这两种构造世界。","assumptions":"纯教学构造，潜在结果只作识别边界说明；没有真实处置或随机实验。","boundary":"若监测离线未取得y，本算例不能成立；若原目标根本不是现行响应下事件，也须按其原合同另评，不能改标签迁就算式。"}],"counterexamples":[{"identity":"constructed_boundary","text":"预警后没有事件，所以必定是误报。","effect":"先核目标与完整标签；仅对明确现行响应目标及事前阈值才能作限定分类，不能由一句无事件推断。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"预警触发响应，所以任何错误预测都不应计分。","effect":"冻结目标若仍有完整标签，仍然可计分；另行识别响应效果。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"20次分箱频率完全匹配，证明模型永久校准。","effect":"有限构造仅表明这批样本的关系，长期、子群和迁移仍需检验。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"只见接受服务者的结果，可以给所有申请人报告同样准确率。","effect":"缺少未接受者的标签或有效识别依据，直接外推不成立。","sourceIds":["theory"]}],"questionAnswers":[{"question":"p=0.8、y=0为什么损失0.64而不是0.2？","answer":"本讲二元Brier是概率误差平方，(0.8−0)²=0.64；0.2是预测给未发生的概率。","basis":"本节原文及上述公开推导"},{"question":"无事件可同时兼容哪两种因果情况？","answer":"原本也不会发生，或本会发生但被响应避免。只见行动后零不能区分。","basis":"本节原文及上述公开推导"},{"question":"模型总体报0.5并有一半事件，是否说明分辨率好？","answer":"不说明。所有人同概率可以总体匹配，却分不开构造中的0.2和0.8两组。","basis":"本节原文及上述公开推导"},{"question":"响应制度改变是否必须丢弃旧评分？","answer":"不应。目标相同则报告性能变化与比较限制；目标改动则另立登记，旧结果保留。","basis":"本节原文及上述公开推导"},{"question":"标签缺失能否按保守方式记零？","answer":"不能。零是确认未发生，未知必须保留，另记录覆盖与缺失机制。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-5/figures/section-12-5.png","alt":"原预测怎样？，冻结目标＋完整标签，计算得分；响应改变多少？，需要相称因果比较，无事件不足以识别；采用是否合宜？，规范／分配／保护，权限另核；构造p=0.8，y=0，Brier=0.64，标签缺失则不能算；已观察Y(行动)=0，Y(无行动)仍可0或1，效果未被单独识别；准确或某项有效，都不单独产生，执行权限。三列并行；左列评分不能替代中列效果识别或右列规范与权限判断。","caption":"三列并行；左列评分不能替代中列效果识别或右列规范与权限判断。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。将来交互可切换完整零标签与缺失标签，缺失状态必须禁用评分而非默认为0。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"一手论文的正式问题设定适合说明预测与部署分布的关系；具体得分及因果不可识别另用公开构造展示。"},"openQuestions":["现实部署的缺失标签、响应强度和分配影响未给定，不能从这些构造估计实际性能或避免损害。"],"taskId":"S-12-5","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2518—2546行；每节精确范围见sourceRefs","claim_support":["12.5：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"perdomo2020","title":"Performative Prediction","url":"https://proceedings.mlr.press/v119/perdomo20a/perdomo20a.pdf","source_type":"primary","version_or_date":"ICML2020，PMLR119:7599—7609","locator":"PDF第1页Abstract与§1首两段；第3页§2.1","claim_support":["预测用于决策可能改变结果；模型依赖分布的形式化问题设定"],"limits":["只引问题设定，未用其定理证明任意响应有效，也未执行其模拟。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-12-5/lecture.md","sourcesPath":"/reading-assets/S-12-5/sources.json","sourceSlicePath":"/reading-assets/S-12-5/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-5/diagrams.md"},"12.6":{"title":"12.6　早期信号、反向信号与触发点","lead":"真正有用的提前量，要数到保护能够完成，而不是数到屏幕上出现警报。信号的责任是触发复核；它不能代替路径解释、规范判断与行动权限。","explanation":["原文定位：第2547—2554行；原文锚点 section-12-6；短引文：‘算法提前发现并不保证最后一位受影响者能在伤害前获得保护’。本题源切片逐字附后，讲解与原文分开。","早期信号应由所讨论路径的机制先行产生，并有可观察定义。例如积压路径的早期变化可以是到件量持续超过处理量，不是提前把最终积压结果换个小数字重复一遍。需登记信号的观察位置、口径、时间窗与路径关系；没有这些桥接，任何先发生的现象都可能被事后包装成先兆。","反向信号针对关键条件失效或竞争路径获得支持。它不必直接证明最终结果绝不发生，而是使当前路径的依据变弱。两类信号都要在结果前登记，并规定什么记录算观察到、什么只是监测缺失；只搜支持材料会让前瞻失去失败可能。","触发点把观察接到复核，复核对象包括对象身份、路径条件、概率表达、规范与授权。发现信号不是自动获准采取行动；若已有明确合法的预授权流程，仍按该流程的条件和边界执行，不能从本节抽象规则自行创造权限。","高风险的否决触发点应事前明确：保护底板突破、关键受影响者无法退出、数据来源失真、校准恶化等。它们需要依适用规则暂停或否决相应方案并复核保护，不是只把置信度小幅调低继续原计划；也不意味必须停止与该缺陷无关的全部工作。","时钟的终点是可完成的行动或保护起效。发现、核验、发布、触达、理解、筹资或调配、转移或起效分别可能耗时，且不同位置耗时不同。不能用平均触达替最后或最难触达者的可完成性。并行环节应按依赖关系计算关键路径，串行时延才直接相加；未知时延要保留为未知或有依据区间。","算法提前量是危险发生时点减发现时点；实际保护余量还要减掉后续完成所需时间。技术上提前不等每个受影响者都来得及，通信、理解、资源与实际能力可能成为瓶颈。处理瓶颈不能只增加预测精度，更要核查末端条件和保护责任。","警报后未发生损害仍要回到冻结目标与标签：若目标是在现行响应制度下的实际事件、有完整标签和预定阈值，可以登记业务假阳性；至于损害是否被应对避免，需要另作因果比较。未触达者和资料缺失者不得默认为安全，也不能用“保护成功”事后救援所有预警。","三个易混比率要同时写分子、分母和人群时窗。在固定二元分类口径下，业务假阳性率FPR=FP/(FP+TN)，警报中虚警比例FAR=FP/(TP+FP)，漏报率FNR=FN/(TP+FN)。名称在不同业务可能不一致，公式比缩写更重要；分母为零则该比率未定义，不能自行填零。精确率TP/(TP+FP)与召回率TP/(TP+FN)可另报，不应互换。"],"distinctions":[{"leftTitle":"早期信号","leftText":"机制预计先产生的观察变化。","rightTitle":"结果缩小版","rightText":"不经机制桥接地把结局提前描述。"},{"leftTitle":"反向信号","leftText":"削弱路径关键条件或支持竞争解释。","rightTitle":"绝对排除结果","rightText":"需更强证据，不能自动得出。"},{"leftTitle":"算法提前量","leftText":"危险时点减检测时点。","rightTitle":"保护余量","rightText":"还扣除触达、理解、资源及行动起效时延。"},{"leftTitle":"假阳性率","leftText":"在全部真实阴性中，误报所占比例。","rightTitle":"警报虚警比例","rightText":"在全部警报中，误报所占比例。"},{"leftTitle":"触发复核","leftText":"检查条件和责任是否仍成立。","rightTitle":"自动授权","rightText":"不能由观察信号自行产生。"}],"boundaries":["无反向信号可能因为未监测，不等关键条件持续成立。","未知时延不能用零代替；平均及时不等每个承担位置及时。","数据失真等否决点应触发相称暂停与保护，不可只改措辞照常执行。","业务误报与响应因果效果是两项不同问题，不能用一个分数代替另一项。"],"questions":["第一对象为何晚3分钟？","FP=18、TN=72、TP=8时，两种虚警指标是什么？","触发点是否禁止一切预授权程序？","警报后未受损，能否认定预警有因果效果？"],"diagramPath":"/reading-assets/S-12-6/figures/section-12-6.png","caseLinks":[{"title":"真实制度设计：WMO将传播和响应能力分列","href":"https://wmo.int/resources/wmo-bulletin/wmo-bulletin-vol-72-1-2023/overview-of-early-warnings-all-executive-action-plan-2023-2027"}],"caseNotes":[{"title":"真实制度设计：WMO将传播和响应能力分列","text":"WMO在2023年公布的全民早期预警行动计划概览把风险知识、监测预报、警报传播沟通、准备与响应能力列为四个支柱。该公开设计把传播与响应保留为独立建设环节，适合提醒读者不能用检测完成替代端到端保护完成。","sourceLabel":"WMO Bulletin，2023-05-05","sourceUrl":"https://wmo.int/resources/wmo-bulletin/wmo-bulletin-vol-72-1-2023/overview-of-early-warnings-all-executive-action-plan-2023-2027","sourceLocator":"开篇首段及四项支柱列表；Year One—2023之Warning dissemination and communication与Preparedness to respond小节","boundary":"这是实际发布的计划结构，不是各年度目标已经达成的证据；也未以其证明某地区保护效果或本讲时延数字。","href":"https://wmo.int/resources/wmo-bulletin/wmo-bulletin-vol-72-1-2023/overview-of-early-warnings-all-executive-action-plan-2023-2027"}],"sourceRefs":[{"section":"12.6","start_line":2547,"end_line":2554,"startLine":2547,"endLine":2554}],"outputId":"section-12-6","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先说明路径为何产生该先行变化，登记可观察信号与相反证据。","结果前固定阈值、时间窗、数据缺失处理和否决触发点。","观察触发复核而非自动行动，逐项核对象、路径、表达、规范及权限。","以保护可完成为时钟终点，逐个承担位置核关键路径和资源。","按冻结目标计算业务指标，分别报告分母；避免损害效果另行识别。"],"teachingExamples":[{"title":"教学构造：先行与反向信号必须连到机制","text":"虚构队列初始积压6，未来两小时每小时到件2、处理1，于是积压7再8。事前登记早期信号为第一小时完整记录显示到件2且完成1，反向信号为第二小时有证据表明处理能力升至3且已实际处理3。在后者发生时终点为6，不再是原路径的8。只看到“扩容申请已递交”不等实际处理提高。","assumptions":"队列、数字和判据全为教学构造，无实际系统实验。","boundary":"若到件漏记或完成不实，信号身份失效，应查资料来源；反向信号只改当前路径，不证明永不积压。"},{"title":"数学构造：30分钟预警仍可能迟到","text":"设危险时点为30分钟，信号在0分钟发现。完全串行的核验3、发布2、触达8、理解4、资源调配6、行动起效10分钟，总计33分钟，保护余量30−33=−3分钟。另一对象触达仅2分钟，其总计27、余量3。算法提前量同为30，却不能说二者都受到及时保护。若把第一对象触达缩至4，其总计29、余量1；这只是给定条件下的时钟计算。","assumptions":"全部时刻与串行依赖人为设定，未开展真实演练或灾害响应。","boundary":"真实环节可并行、时延有分布且危险时点有误差，应核关键路径和不确定性；此算例不是应急操作建议。"},{"title":"数学构造：同为18次误报，三个分母不同","text":"构造100个同口径且标签完整的对象：TP=8、FP=18、FN=2、TN=72。业务假阳性率18/(18+72)=20%；警报中虚警比例18/(8+18)=9/13≈69.23%；漏报率2/(8+2)=20%。精确率8/26≈30.77%，召回率8/10=80%。两种20%只是本例巧合，并非两个指标相同。","assumptions":"固定阈值、目标、响应制度、人群和期限，100项全部是构造标签。","boundary":"若标签只覆盖接受响应者，不能直接沿用这张全人群混淆矩阵；不由分类结果识别干预挽救数。"}],"counterexamples":[{"identity":"constructed_boundary","text":"预警提前30分钟发出，所以所有人都有30分钟行动。","effect":"核验、触达、理解、资源与起效消耗时间，各人末端能力也不同。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"18次误报意味着虚警率一定20%。","effect":"必须给分母：本构造FPR20%，警报中虚警比例约69.23%。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"发现反向信号后仍只收原路径支持材料。","effect":"反向信号须实质进入复核，必要时撤回路径或降低表达。","sourceIds":["theory"]}],"questionAnswers":[{"question":"第一对象为何晚3分钟？","answer":"串行总时延3+2+8+4+6+10=33，危险30时发生，保护余量−3。","basis":"本节原文及上述公开推导"},{"question":"FP=18、TN=72、TP=8时，两种虚警指标是什么？","answer":"真实阴性中的误报18/90=20%；警报中的误报18/26约69.23%。","basis":"本节原文及上述公开推导"},{"question":"触发点是否禁止一切预授权程序？","answer":"不是。已有适用预授权可依其条件执行，但观察本身不新造授权。","basis":"本节原文及上述公开推导"},{"question":"警报后未受损，能否认定预警有因果效果？","answer":"不能单独认定，需比较没有该响应时的相应结果；原预测仍按冻结目标和标签评价。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-6/figures/section-12-6.png","alt":"构造：危险t=30，信号发现t=0，算法提前30分钟；核验3＋发布2，触达8＋理解4，资源6＋起效10；串行总时延33，保护余量−3分钟，尚未及时完成；路径信号与反向信号，结果前登记，资料失真可触发否决；观察后重新复核，对象／路径／概率，规范／授权；报指标必须报分母，FP/真实阴性，FP/警报不是同一量。时延数字是串行教学构造；真实系统须核并行依赖、各位置条件与时间不确定性。","caption":"时延数字是串行教学构造；真实系统须核并行依赖、各位置条件与时间不确定性。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。后续交互可调整每一时延并显示保护余量，但不得把演示滑块当真实应急参数。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"官方行动计划的结构直接支持检测、传播和响应能力须分别考虑；具体时钟用明确构造而不虚构现实成效。"},"openQuestions":["实际人群的触达与资源时延、保护底板和否决权限仍须现场制度及可核资料。"],"taskId":"S-12-6","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2547—2554行；每节精确范围见sourceRefs","claim_support":["12.6：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"wmo2023","title":"Overview of the Early Warnings for All: Executive Action Plan 2023–2027","url":"https://wmo.int/resources/wmo-bulletin/wmo-bulletin-vol-72-1-2023/overview-of-early-warnings-all-executive-action-plan-2023-2027","source_type":"primary","version_or_date":"2023-05-05；网页标示更新2026-09-30","locator":"开篇首段与四支柱列表；Year One—2023传播及响应能力两小节","claim_support":["官方计划将监测预报、传播沟通、准备与响应能力作为不同支柱"],"limits":["是计划设计，不是目标兑现或保护因果效果证据；未采用网页灾情数字和年度指标。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-12-6/lecture.md","sourcesPath":"/reading-assets/S-12-6/sources.json","sourceSlicePath":"/reading-assets/S-12-6/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-6/diagrams.md"},"12.7":{"title":"12.7　前瞻的失败语义","lead":"预测的诚实不只在发布时说得谨慎，也在到期时允许原记录被判为未支持、未决或不能评价。给失败起一个含糊的新名字，并不会使预测变准。","explanation":["原文定位：第2555—2560行；原文锚点 section-12-7；短引文：‘未决不是成功与失败的折中’。本题源切片逐字附后，讲解与原文分开。","本节为到期评价提供五种语义：支持、未支持、未决、目标失效、无法评价。它们应回到事前合同中的目标、身份判据、时窗、材料与成功规则，而不是按作者希望保全面子来挑标签。规则还须事前说明重叠情形如何处理，不能把这五个名称机械当作无需解释的自动分类器。","支持指取得的材料达到原合同支持规则，只支持原范围，不等机制、概率与所有延伸结论均已证实。未支持指原合同的支持标准没有成立；若完整观察与原断言相反，可以具体说明失败。一次概率预测发生或未发生不自动证明该概率错误或正确，应按原规定得分与长期评价。","未决是合同允许且已定义的证据不足状态。例如观测误差区间跨越预先阈值，现有完整材料不足区分两边。它不是半次成功，也不能永远延长期限等到出现有利材料；若后续允许补充观察，应事前登记附加流程，旧到期状态仍保留。","无法评价必须说明评价所必需的哪个条件出问题，如关键数据永久丢失、对象无法追踪、期限定义失去可操作性或执行记录不明。它与未决的边界应由合同说明：前者可指评价程序入口不可用，后者可指入口仍可用但证据不能判定。这个操作性划分是本讲的合同示范，不声称原文给出一套穷尽唯一算法。","目标失效表示原预测对象或同一性判据确实已转换。例如被预测的指定服务单元撤销，其任务与成员并入另一个组织，若原合同未规定承接关系，就不能把新组织的结果冒充旧对象命中。对象变化须有材料，不能因为结果不好就宣布身份改变。","结果后更换目标、期限或圈层范围，或者把几条竞争路径合并成“多少有一点发生”，都不能保留原前瞻的成功资格。可以承认原结果，再以新问题、新对象或新条件建立新版本；旧登记、旧证据与旧评分继续存在，修改理由要可回查。","失败语义是纠错接口，不是卸责语言。未决须指出缺哪项辨别材料，无法评价须说明评价为何不可执行，目标失效须证明身份转换，并交代仍须承担的监测和补救责任。不能靠大量排除困难对象改善命中率；汇总时应同时列各状态数、原登记总量与可评价子集，避免选择性分母。"],"distinctions":[{"leftTitle":"未决","leftText":"合同规定的证据不足，仍不知道答案。","rightTitle":"半次成功","rightText":"未经定义将未知折算为命中，会扭曲结果。"},{"leftTitle":"无法评价","leftText":"评价所需程序、资料或对象条件无法满足。","rightTitle":"预测被证实","rightText":"资料不足不能转成正面证据。"},{"leftTitle":"目标失效","leftText":"有材料支持对象或同一性判据转换。","rightTitle":"事后换对象","rightText":"为了保留成功而挪动预测范围。"},{"leftTitle":"新版本解释","leftText":"另立目标与条件并保留旧结果。","rightTitle":"改写旧成功","rightText":"把新条件倒灌给已到期的旧记录。"},{"leftTitle":"单次事件结果","leftText":"支持特定分类或给出逐案损失。","rightTitle":"概率长期正确","rightText":"需要相应可比登记与校准评价。"}],"boundaries":["五种状态不是随意选的辩护词，判定依据必须可复核。","本讲给未决与无法评价的合同示范边界，不擅自补成理论唯一必要定义。","对象身份转换与资料丢失都需事实支持，不能以失败本身推定。","汇总只报可评价者准确率而隐藏其他状态，会误导对全体登记的理解。"],"questions":["B的有效区间[7,9]为何在本合同下未决？","日志损毁为什么不是自动未支持？","十项中的4/6和4/10能否都报告？","新解释是否不允许？"],"diagramPath":"/reading-assets/S-12-7/figures/section-12-7.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.7","start_line":2555,"end_line":2560,"startLine":2555,"endLine":2560}],"outputId":"section-12-7","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["按原合同核目标、对象身份、时窗、资料与判定标准。","材料满足支持规则则限域标支持，完整相反结果则如实记未支持。","证据不足按预定规则标未决；程序入口破坏说明无法评价的原因。","身份已转换且无合同承接则记录目标失效，不冒记命中。","新解释另建版本，旧记录保留，汇总同时披露各状态与分母。"],"teachingExamples":[{"title":"教学构造：同一阈值合同下的五种到期记录","text":"虚构登记：指定单元A在第2小时末积压B≥8。合同规定精确同口径记录可直接判；只有有效误差区间跨8则未决；核心计数数据丢失且无重建途径为无法评价；A撤销且无承接定义则目标失效。五个独立假想情形分别为：完整B=9支持；完整B=6未支持；有效区间[7,9]未决；日志损毁不能重建无法评价；单元A撤销合并且原身份不延续目标失效。这是替代情形，不是同一次运行同时有五种结局。","assumptions":"所有对象、数字、合同规则与事件为教学构造；原预测为阈值断言而非概率声明。","boundary":"真实合同可能采用其他明确判据；身份继承与误差区间是否可信必须另有材料。"},{"title":"教学构造：改期限得到新结果，不能救援旧预测","text":"原登记预测t=2时B≥8，完整观察B2=6，故原断言未支持。之后t=3时B3=9，作者改说“最终会达到8”不能把t=2记录改为成功。可以用新信息建立t=3或更远的新登记，但需明确注册时刻，不能在已经知道B3=9后假称这是事前预测。","assumptions":"时刻与数值人为构造，没有真实队列观测。","boundary":"原合同若事先预测的是2至3小时窗口，则须按那个原窗口评价；这里明确原目标只是t=2。"},{"title":"数学构造：公布状态分布，拒绝把未知算半成功","text":"假设10项登记到期：支持4、未支持2、未决2、目标失效1、无法评价1。按本构造的预设规则，能二分评价的6项中支持率4/6≈66.67%；全体登记中支持占比4/10=40%。两个比率回答不同问题，均须带分母和另4项状态。不能把2项未决各算半次成功得到5/10=50%并称为命中率，也不能把其余4项隐去。","assumptions":"十项状态为数学构造，二分可评价集的定义也是公开题设。","boundary":"可评价支持比例不等总体校准、因果正确或现实泛化能力；不同任务不能不加权不分口径混算。"}],"counterexamples":[{"identity":"constructed_boundary","text":"到期未决就按成功失败各一半计分。","effect":"未决是证据状态，除非原任务有独立合理且预登记评分规则，不能任意折算命中。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"原单元取消后新团队达标，所以旧预测命中。","effect":"先核身份承接规则，没有则目标失效而非旧成功。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"第三小时命中足以证明第二小时的断言正确。","effect":"时间属于冻结目标，不能后改期限。","sourceIds":["theory"]}],"questionAnswers":[{"question":"B的有效区间[7,9]为何在本合同下未决？","answer":"阈值8落在区间内，既可能达到也可能未达到；入口资料有效但不足区分。","basis":"本节原文及上述公开推导"},{"question":"日志损毁为什么不是自动未支持？","answer":"按本示范合同，不能恢复标签，评价无法执行；没有证据不能填成完整反面结果。","basis":"本节原文及上述公开推导"},{"question":"十项中的4/6和4/10能否都报告？","answer":"可以，须分别称可二分评价子集支持率与全部登记支持占比，并披露其余状态。","basis":"本节原文及上述公开推导"},{"question":"新解释是否不允许？","answer":"允许新版本，但登记时点、目标、依据和旧失败都必须保留，不能倒改原成功资格。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-7/figures/section-12-7.png","alt":"原断言：t=2时B≥8，完整B=9：支持，完整B=6：未支持；有效区间[7,9]，跨越原阈值，按示范合同：未决；核心标签不可恢复，说明评价入口故障，无法评价；原对象已撤销，无身份承接规则，目标失效不计命中；可以另建新版本，新目标／条件／时间，旧记录继续存在；不后改期限或范围，不把未知算半成功，汇总保留全部分母。图中对象、区间与判据均为合同教学构造；不是替现实项目自动判定状态。","caption":"图中对象、区间与判据均为合同教学构造；不是替现实项目自动判定状态。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。未来可选不同到期材料，但需始终显示原合同，不能在切换结果时隐性改变判据。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节是原文评价合同与状态语义，使用逐一可核的教学构造更能隔离逻辑边界；未将缺乏完整事前合同的历史事件强行分类。"},"openQuestions":["实际项目须先提供冻结合同、身份承接规则及到期材料，才能判定五类状态；目前没有现实项目可作实证分类。"],"taskId":"S-12-7","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2555—2560行；每节精确范围见sourceRefs","claim_support":["12.7：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-7/lecture.md","sourcesPath":"/reading-assets/S-12-7/sources.json","sourceSlicePath":"/reading-assets/S-12-7/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-7/diagrams.md"},"12.8":{"title":"12.8　从前瞻到有限选择的桥","lead":"“这样可能更好”可以成为供审议的建议，却不能直接变成对别人有约束力的命令。条件后果、价值比较和现实权限之间，每一步都有自己的理由。","explanation":["原文定位：第2561—2566行；原文锚点 section-12-8；短引文：‘推荐不产生执行权限’。本题源切片逐字附后，讲解与原文分开。","前瞻给出某些条件下可能发生什么，不自行决定哪种后果值得追求，也不决定谁应承担成本。高概率可以增加对某后果的判断力度，却不能单独提高对他人的行动权限；平均收益高也不能取消少数位置的权利。","形成分析推荐前，须明示规范前提、证据状态、受影响位置、候选方案、成本收益与改判条件。此时可以给有理由的局部判断和条件建议，不必因为实际执行尚未授权就禁止一切分析；但要清楚标注供审议身份和未满足的现实采用条件。","进入现实采用前要补齐选择主体与管辖权，受影响及低权力位置、权利底线、方案及成本收益分布、授权、停止、申诉、回滚和补救。这里调用既有N、PF、J、O与C12，而非另造一条“预测很准所以可以执行”的捷径。","按§14.3（2892—2910行），N须运行时明确登记。N1只阻止解释直接授权，不独自给正向目标；N2要求保护不降级，N3要求高影响判断可纠错，N4反对无限不可退出的单方牺牲，N5阻止把存续和筛选当正当。采用哪些原则、它们作目标还是约束、怎样处理冲突，都须公开，不能默用一条善意口号。","PF是不能与效率随意兑换的保护底板。§14.8（2968—3000行）要求十项分别绑定到真实机制、责任、停止、申诉、复核、回滚与到期；纯形式勾选不够。涉及人类、有感、混合或未知对象时不能自称纯技术而削减保护。底板也不穷尽全部实体权利，具体权益仍需独立依据。","J回答谁针对什么对象做哪个动作、在哪个地域和期限内有何有效依据。§14.6（2940—2953行）要求单一有效原子元组覆盖同一动作的完整范围，不能把一条“能读取A”与另一条“能修改B”拼成“能修改A”。多主体合法接续可以成立，但每个动作分别核自身权限和输入条件。","O1冻结描述、证据与不确定性；O2显式列规范、承担者和冲突；O3比较包括不行动的方案并查授权边界；O4落实受限执行及可监测、停止、申诉、回滚、补救和到期。C12按§4.14.1（908—925行）检查桥接组件完整，既不替人选择价值，也不代替现实制度的法律效力。","不行动也必须评价后果和责任：旧规则可能继续产生伤害，等待可能错过保护窗口，既有义务不会因模型建议不新增行动而消失。应明确观察、保护和重开评估的责任，而不是把不行动自动包装成中性、无成本、无需说明的选择。","缺口应局部定位：证据不足阻断相应判断，规范未明阻断依赖它的推荐，授权未足阻断相应执行。独立成立的描述、明示前提的条件建议和补证需求仍可保留；不能一方面越权执行，另一方面也不能因某个门未过而拒绝所有有依据的帮助。"],"distinctions":[{"leftTitle":"分析推荐","leftText":"明示前提下有依据的局部或条件建议。","rightTitle":"现实采用","rightText":"还需完整保护、权限、程序与纠错条件。"},{"leftTitle":"高概率","leftText":"增强所问后果的描述判断。","rightTitle":"强制他人的权力","rightText":"需要独立有效授权及正当性。"},{"leftTitle":"平均收益","leftText":"汇总某种收益或成本的指标。","rightTitle":"分配及权利","rightText":"谁承担、是否可拒绝、哪些底线不可兑换。"},{"leftTitle":"C12检查","leftText":"规范桥接组件是否齐备。","rightTitle":"价值与现实授权来源","rightText":"不能由检查表本身创造。"},{"leftTitle":"不新增行动","leftText":"候选新增行为没有实施。","rightTitle":"没有持续责任","rightText":"旧义务、损害与保护需求仍可能存在。"}],"boundaries":["未授权不禁止供审议的分析推荐，但必须阻断把它当可执行命令。","总体净收益为正不能单独覆盖低权力位置的权利损害。","一种动作的多个不完整授权片段不能拼接为有效完整权限。","N1是否定门，不足以自行决定应选哪个正向方案。"],"questions":["C12能否代替选择价值？","B方案平均+1.5为何仍可能被否决？","能读A且能改B，能否改A？","没有执行授权时还能交付什么？"],"diagramPath":"/reading-assets/S-12-8/figures/section-12-8.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.8","start_line":2561,"end_line":2566,"startLine":2561,"endLine":2566}],"outputId":"section-12-8","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["把条件后果与值得追求的目标分开，列证据与不确定性。","明确正向规范和保护约束，逐位置比较候选与不行动的成本收益。","形成供审议的有限推荐并给改判条件，保留尚缺权限的身份。","现实采用前核主体、J、PF和O1—O4，再以C12检查桥接完整。","执行必须能停止、申诉、回滚、补救并到期；不行动也记持续责任。"],"teachingExamples":[{"title":"数学构造：平均收益会隐藏集中损害","text":"虚构A方案对9个位置各带来效用+2，对1个低权力位置带来−30，总和18−30=−12、平均−1.2；另一B方案对9个位置各+5，对最后位置−30，总和45−30=15、平均+1.5。即使B平均为正，若−30对应题设中禁止转移的权利伤害，B仍不能只凭平均收益被采用。数字效用只展示汇总遮蔽，权利约束不是从数值大小推导的。","assumptions":"效用、人群与权利约束均人为给定；这里没有现实损害计量或人际效用可比性证明。","boundary":"若不具备可比效用，连求和都不能当现实比较；权利约束须独立明示，不能由作者见到不喜欢的结果临时添加。"},{"title":"教学构造：可以推荐审议，不等可以改排班","text":"虚构团队预测自愿轮换方案可减少等待。分析者明确目标为减少等待且不降低既有休息保护，比较现状、增援与自愿轮换，并列出谁增加负担、何种证据会改判，因而可建议将自愿轮换提交审议。若其没有排班修改权限且成员同意、申诉和回滚机制未落实，不能直接改真实排班。","assumptions":"团队、目标和预测全为教学构造，无真实人员或组织操作。","boundary":"不把自愿作为已证事实；实际同意须可拒绝、可撤回且符合适用制度，具体劳动规则未在此给出法律判断。"},{"title":"形式构造：权限不能跨对象拼接","text":"假设记录J1只允许主体甲在本周读取对象A，J2只允许甲在本周修改对象B。候选行为是本周修改A。J1动作不匹配，J2对象不匹配，所以没有一条记录充分覆盖该动作。把两条的对象列与动作列组合成笛卡尔积会造出不存在的权限。","assumptions":"所有主体、对象与授权均为形式构造；假设记录内容有效但范围如题设。","boundary":"这不否定合法流程中的多个主体分别完成不同动作；每一动作仍须有自己的完整覆盖。"}],"counterexamples":[{"identity":"constructed_boundary","text":"预测置信度99%，所以有权强迫任何人承担防范成本。","effect":"置信度属于条件后果判断，成本分配、权利和管辖另核。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"执行权限尚未给出，因此连条件推荐也不能写。","effect":"可写有证据且明示规范的供审议推荐，只不能把它包装为已授权执行。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"模型建议不行动，因此不再需要保护和观察责任。","effect":"不行动仍有持续后果与既有责任，须评估并安排重开条件。","sourceIds":["theory"]}],"questionAnswers":[{"question":"C12能否代替选择价值？","answer":"不能。先登记明确规范和冲突，C12检查相关桥接条件，不暗中创造目标。","basis":"本节原文及上述公开推导"},{"question":"B方案平均+1.5为何仍可能被否决？","answer":"题设权利约束禁止把该伤害转嫁给最后位置，平均数不能取消独立约束。","basis":"本节原文及上述公开推导"},{"question":"能读A且能改B，能否改A？","answer":"不能，两条分别缺动作或对象覆盖，不能拼成新权限。","basis":"本节原文及上述公开推导"},{"question":"没有执行授权时还能交付什么？","answer":"有依据的描述、明示规范的条件推荐、代价和改判条件，以及现实采用尚缺事项。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-8/figures/section-12-8.png","alt":"条件后果，证据／不确定性，不自行选价值；供审议分析推荐，明示规范与分配，方案／代价／改判；现实采用条件，主体／PF／J／O，C12完整桥接；高概率不造权限，平均收益不抹权利；没有执行权限，仍可形成条件建议，不能冒充可执行令；停止／申诉／回滚，补救／到期／责任，须真实可达。不行动也须核持续损害与责任；图示是规范结构，不构成任何现实动作授权。","caption":"不行动也须核持续损害与责任；图示是规范结构，不构成任何现实动作授权。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。后续交互可标出某一缺失项具体阻断何种结论，保留不受影响的分析内容。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节是规范桥接与权限逻辑，使用明确虚构的方案比较和形式元组足以展示边界；没有现实决策档案可验证所有授权、保护及纠错条件，因此不将历史成败强行认证为规范合格。"},"openQuestions":["实际选择仍需本次规范、受影响者资料、有效授权及可达纠错证据；本讲不签发任何现实采用资格。"],"taskId":"S-12-8","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2561—2566行；每节精确范围见sourceRefs","claim_support":["12.8：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"connections","title":"原书规范桥接相关章节","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.14.1第908—925行；§14.3第2892—2910行；§14.6第2940—2953行；§14.8第2968—3000行；§14.9第3002—3009行","claim_support":["C12的分析推荐与现实采用区分；N、PF、J、O定义及不行动责任"],"limits":["理论规范程序的忠实解释，不认证现实制度法律效力或具体授权。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-8/lecture.md","sourcesPath":"/reading-assets/S-12-8/sources.json","sourceSlicePath":"/reading-assets/S-12-8/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-8/diagrams.md"},"12.9":{"title":"12.9　方案集必须包含行动与不行动","lead":"比较方案不是给既定动作找理由。先把真正能选、值得比较的路径摆出来，尤其不能删掉不新增行动的基线，也不能把主动维持现状误写成什么都不做。","explanation":["原文定位：第2567—2581行；原文锚点 section-12-9；短引文：‘不行动可能让现状自然变化’。本题源切片逐字附后，讲解与原文分开。","在用户或任务请求选择时，逐项检查六类：维持现状、主动行动、延迟行动、试探小步、退出或转移、明确不行动。检查的是适用性，不是强制凑齐六个按钮；不适用要说明约束，适用才建立真实可比较方案。具体任务可增加类别，单纯解释或核对任务则不强制附带行动清单。","维持现状可能持续投入资源、维护规则、执行保护和承担成本；不行动指不实施本次候选新增行动，已有机制仍会自行变化。按§14.4（2912—2927行），不行动基线仍保留既有维护、正在执行行为和独立义务，不能把“不新增”偷换成“关闭所有已有保护”。主动维持方案与基线差在哪里必须逐项说明，不能只换名称。","维持现状要查隐性成本、持续伤害与锁定；主动行动要查权限、不可逆性和跨圈层成本外溢。改变很快不等值得做，稳定也不等正当，两个方向都要公开规范前提和受影响位置。","延迟行动是有时钟的方案，须写等什么材料或程序、多久、谁观察、到何时重开；等待自身可能让损害累积或错过窗口。不能把缺证无限拖成无需负责，也不能把计划以后执行登记为已经发生。","试探性小步须给出学习对象、区分信号、规模、期限、停止、回滚和成本承担。规模小只说明某个量小，不保证低风险或可逆；受影响者、隐私、不可逆信息泄露与负担转嫁仍需核。详细条件由12.11继续展开。","退出或转移可能结束不合适关系或对象，却不自动消除依赖者、既有责任和历史。应核谁能退出、谁不能、服务或责任由谁接续、记录如何保留。若没有合格承接，不能为凑一个选项虚构“转移即可”；退出也不能被无限责任绑架。","不行动必须登记基线时点、预期路径、观察计划、重新开启条件与责任主体。其他主体、资源和时钟还在推进，基线不是静止照片。给出这一基线才能比较新增干涉带来什么，否则很容易把“必须做点什么”暗藏成前提。","六类不是天然互斥的世界类别：一个组合方案可以先监测、有限试探、达到阈值再转移。但登记时应拆清阶段、触发和资源，不得把同一动作重复计入多个方案收益，或以组合名称掩盖执行权限缺口。现实采用仍须12.8的桥接，方案清单本身不授权。"],"distinctions":[{"leftTitle":"主动维持现状","leftText":"需要明确资源和执行来保持目标状态。","rightTitle":"不新增行动","rightText":"保持原有流程，状态仍可能自然变化。"},{"leftTitle":"六类适用性检查","leftText":"逐类说明为何适用或不适用。","rightTitle":"六个必须存在的方案","rightText":"会迫使人虚构无资源或无权限选项。"},{"leftTitle":"有时限延迟","leftText":"等指定信息并承担等待代价。","rightTitle":"无限拖延","rightText":"不设观察、期限或重开责任。"},{"leftTitle":"退出或转移","leftText":"明确结束范围及依赖承接。","rightTitle":"责任消失","rightText":"旧义务和历史不由改名自动消除。"},{"leftTitle":"解释任务","leftText":"回答概念或证据问题。","rightTitle":"选择任务","rightText":"要求比较并提出方案，才需相应完整集合。"}],"boundaries":["不行动基线不能默认停掉既有义务，也不能默认没有成本。","明确不适用的方案不得为填表而虚构。","小步、延迟、维持和退出都可能有高影响后果，名称不保证安全。","同一组合方案的资源与效益须避免重复计数，候选方案不是执行授权。"],"questions":["队列不行动为何积压8而不是不变6？","保持6需要什么额外条件？","退出没有承接方时该如何登记？","不行动最少要记录什么？"],"diagramPath":"/reading-assets/S-12-9/figures/section-12-9.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.9","start_line":2567,"end_line":2581,"startLine":2567,"endLine":2581}],"outputId":"section-12-9","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["确认任务是否请求选择，若是逐项检查六类适用性。","明确不行动基线保留哪些已在执行的义务与维护，区别新增主动维持。","对适用方案登记真实动作、对象、时间、资源、承担者及边界。","说明延迟、试探和退出各自风险，不以名称保证安全或可行。","同窗比较变化中的基线，指定观察、重开条件和责任，采用另核权限。"],"teachingExamples":[{"title":"教学构造：同一个虚构队列中的六类适用性","text":"虚构服务队列t=0积压6，每小时到件2、原有处理1，比较未来两小时。明确不行动是保持原服务而不新增资源，终点8；主动维持是另增每小时1单位处理以保持积压6；主动改善是相对原处理1每小时新增2、总处理3，终点4；延迟是首小时原处理1、第二小时经批准增至3，积压7再6；小步试探是首小时增至2并监测，第二小时按事前规则处理；退出或转移因当前没有可验证承接方而记不适用，不编造转接能力。每个新增方案都仅为候选。","assumptions":"数值、能力及观察期全为教学构造，无真实服务部署；原处理1作为既有服务，不行动不取消它。","boundary":"没有比较资源成本或实际授权，不能仅因终点4最小就宣布应立即实施；试探第二小时尚取决于观测，不能当固定终点。"},{"title":"数学构造：自然衰减揭示维持和不行动的差别","text":"纯技术虚构库存初值10，每期自然损耗2且没有其他既有投入。连续两期不新增补充得8再6；若每期主动补充2，则保持10再10，但新增投入总计4。称后一方案“没有改变最终库存”不等它“没有行动和成本”。","assumptions":"损耗、投入与线性更新I下一期=I−2+补充均为人为假设，无实际实验。","boundary":"实际库存可能有阈值、需求和保护义务，不应用这个纯构造推断人的照护或组织责任。"},{"title":"教学构造：可审计的不行动基线","text":"给前述队列的不行动记录：基线t=0、B=6；预期t=1为7、t=2为8；每小时核对到件与实际完成；若任一完整记录B≥7则重开方案复核；虚构值班角色R负责观察和记录。重开只是复核，不自动增加处理资源。若记录缺失，标未知并触发资料复核，不把缺失作低风险。","assumptions":"观察规则和责任角色仅作教学模板，未给任何真实个人分派工作。","boundary":"真实责任须被适格主体接受且具备能力、时间与权限；本模板不能证明现实已有人承接。"}],"counterexamples":[{"identity":"constructed_boundary","text":"维持现状和不行动最终都想稳定，所以合并一项。","effect":"维持可能有持续新增投入，不行动基线可能衰减；应按真实动作与资源区分。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"必须列六类，所以即使没有接收方也写转移可行。","effect":"六类检查不等六项可行，缺承接应说明不适用或待证。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"只解释一个概念，也必须给出六种行动方案。","effect":"未请求选择不强制行动清单，输出范围由任务决定。","sourceIds":["theory"]}],"questionAnswers":[{"question":"队列不行动为何积压8而不是不变6？","answer":"既有处理每小时1而到件2，每小时净增1，两小时由6变8。","basis":"本节原文及上述公开推导"},{"question":"保持6需要什么额外条件？","answer":"每小时处理提高到2，新增每小时1单位且须另有资源、授权及保护条件。","basis":"本节原文及上述公开推导"},{"question":"退出没有承接方时该如何登记？","answer":"说明当前不适用或缺少承接证据，不能虚构可行转移。","basis":"本节原文及上述公开推导"},{"question":"不行动最少要记录什么？","answer":"基线时点、预期路径、观察计划、重开条件与责任主体，并保留既有义务。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-9/figures/section-12-9.png","alt":"维持现状，需要什么持续投入？，有无伤害与锁定？；主动行动，改变哪条路径？，权限与溢出如何？；延迟行动，等什么、等多久？，等待代价谁承担？；试探小步，学什么、何时停？，能否回滚补救？；退出或转移，谁承接、谁不能退？，无承接不造方案；明确不行动，基线仍在变化，观察／重开／责任。选择任务保留明确不行动基线；不适用说明理由，未请求选择不强制行动清单。","caption":"选择任务保留明确不行动基线；不适用说明理由，未请求选择不强制行动清单。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。未来可展示适用与不适用理由，不能因隐藏一类卡片而删掉不行动基线。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节说明方案生成与基线身份。使用明确构造的同一对象控制条件，避免把缺乏完整权限与资源档案的历史做法冒充真实可选方案。"},"openQuestions":["实际成本、权限、服务承接与低权力位置尚无材料；示范方案不构成现实最优推荐。"],"taskId":"S-12-9","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2567—2581行；每节精确范围见sourceRefs","claim_support":["12.9：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"connections","title":"原书不行动与维持现状的规范比较","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§14.4第2912—2927行；§14.9第3002—3009行","claim_support":["不行动指不新增本次候选行为，既有维护与义务仍须另记；基线自然变化及不作为责任"],"limits":["理论解释，不认证具体服务义务、承接资格或执行权限。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-9/lecture.md","sourcesPath":"/reading-assets/S-12-9/sources.json","sourceSlicePath":"/reading-assets/S-12-9/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-9/diagrams.md"},"12.10":{"title":"12.10　统一方案比较卡","lead":"统一比较卡统一的是问题、基线和责任，不是把所有价值强行压成一个总分。信息有没有帮助、动作能否共同合格、资源能否同时支撑，是三个要分别证明的问题。","explanation":["原文定位：第2582—2600行；原文锚点 section-12-10；短引文：‘应保留多维结果和公开冲突’。本题源切片逐字附后，讲解与原文分开。","每个方案对同一基线、目标和期限比较。最低记录包括方案描述、前瞻引用、规范前提、受影响者、权利底线、预期路径、最坏可接受结果、跨圈层溢出、成本收益分布、信息价值、锁定风险、可逆性、资源成本、执行者、授权、停止、回滚和补救。只交“收益大、风险可控”没有提供可复核比较。","目标与路径要说明改什么机制；保护底板要指出不可接受损害，不能拿平均收益代替；分配要写谁得谁付与何时发生，总量净值不够；跨圈层溢出要看成本是否向外部化，主圈层指标不能独占评价。","信息价值问新观察能否区分机制、路径或改变有依据的选择，不看行动是否戏剧化。可逆与锁定问是否真的能停、退、补救，不接受口头承诺。权限须指明能决定、执行和受理申诉的主体与有效范围，职位或模型推荐不够。不行动仍沿变化中的基线，不能填零成本。","多维结果若没有合理共同量纲与公开权衡规则，就保留向量、冲突及不同规范前提下的排序。模型可以说明在某组已公开规范下偏好哪个方案及为何改判，但不替适格主体作有约束力的最终决定。强行求和既可能隐藏权利底线，也可能偷偷设定人际效用交换率。","受限信息价值公式EVSI=E_Z[max_a E(U(a,θ)|Z)]−max_a E[U(a,θ)]。这里θ为状态，a为动作，Z为信息，U为预先认可且可计算期望的效用。公式比较获知Z后可以因信号选择动作，与不知道Z时先选一个动作的最优期望。效用与概率都要有身份；模型条件计算不是现实已验证收益。","非负结论需要信息免费且可忽略，行动集合和目标不变。若取得信息后仍可采用原最优动作，至少能做到原来那样好。现实调查耗时、隐私、资源，可能改变对象或使动作过期，因此毛EVSI不等净价值。未能量化的隐私与权利成本也不能默认零；不能为使用公式强行货币化。","两条线索可能分别不改变决策，联合才有价值，故信息价值未必可逐条相加。知识也有不依赖本次动作的理解价值，不应因本公式EVSI=0就说研究毫无价值。12.10.1进一步说明未知下共同动作何时可行，12.10.2检查多动作共享资源；父节比较卡不能代替这两道检验。"],"distinctions":[{"leftTitle":"统一比较","leftText":"共同问题与基线下逐项记录。","rightTitle":"统一标量","rightText":"只有额外正当权衡与量纲条件下才可能成立。"},{"leftTitle":"毛EVSI","leftText":"在固定模型内允许信息后选择的期望增益。","rightTitle":"净价值","rightText":"另含调查时间、资源、隐私和机会代价。"},{"leftTitle":"决策信息价值零","leftText":"这项信息在给定目标和动作下不改善选择。","rightTitle":"没有知识价值","rightText":"理解等价值可以独立存在。"},{"leftTitle":"条件偏好","leftText":"明示规范下供审议的理由。","rightTitle":"最终约束决定","rightText":"需有资格的主体与有效程序。"}],"boundaries":["最大化公式不把效用前提变成自然事实，不自动授权收集信息。","免费可忽略条件失败时，不能沿用毛EVSI非负来宣称现实调查总有益。","两线索单独无用不代表联合无用，信息价值一般不可机械相加。","比较卡字段齐全仅提高可审查性，不认证事实正确与现实权限。"],"questions":["EVSI证明中最关键的不等式是什么？","异或例只见X为何无增益？","成本0.6时净值是多少？","统一比较卡为何不必统一总分？"],"diagramPath":"/reading-assets/S-12-10/figures/section-12-10.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.10","start_line":2582,"end_line":2600,"startLine":2582,"endLine":2600}],"outputId":"section-12-10","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["对同一基线、目标和期限填全比较字段，保留各承担位置。","无合理共同尺度时保留多维结果，公开规范冲突和条件偏好。","信息价值先明确状态、信号、动作和效用，再说明其条件身份。","证明免费可忽略且行动集合不变时毛信息价值非负，现实另扣相称代价。","检查线索联合效应、共同可接受动作和共享资源，再交适格程序选择。"],"teachingExamples":[{"title":"数学证明：受限EVSI非负","text":"设有限非空固定动作集、效用期望存在，取无信息最优动作a*。对每个信号z，max_a E[U(a,θ)|Z=z]≥E[U(a*,θ)|Z=z]。对Z取期望并用全期望公式，左侧≥E[U(a*,θ)]=max_a E[U(a,θ)]，相减得EVSI≥0。免费且可忽略保证信号后的可行策略仍含固定a*；行动集合变化则这一步可能不成立。","assumptions":"有限概率模型、有限动作集及可积效用为明示条件；这是代数论证，未进行现实实验。","boundary":"非负是毛期望值结论，不证明每个具体信号都改善、不保证现实采集净值为正或具有权限。"},{"title":"数学构造：两条各自无增益的线索联合有价值","text":"独立公平比特X、Y的四种组合00、01、10、11各概率1/4，状态θ=X异或Y；动作a∈{0,1}，猜中得1否则0。无信息θ均匀，最佳期望1/2。只见X或只见Y，另一个仍均匀，期望仍1/2，单条EVSI=0。联合见X、Y则准确计算θ，每次得1，联合EVSI=1−1/2=1/2。若两条信息合计采集成本在同一效用尺度为0.6且无其他变化，净值0.5−0.6=−0.1。","assumptions":"全部分布、效用与成本人为给定，未实际采集信息。","boundary":"不外推现实信息总能联合消歧；成本可比性也是题设，真实隐私和权利约束不能任意折算。"},{"title":"教学构造：多维比较不强行求和","text":"虚构方案A等待时间少2小时但新增隐私暴露，方案B不增加暴露但仅少1小时。没有公开的隐私约束和时间权衡时，不应将“2−隐私分”伪装成客观总分。可以分别报告等待、暴露对象、撤回难度、保护底线和资源，再在明示“不得新增特定暴露”的前提下将A排除。","assumptions":"方案和效果为构造，不描述真实用户数据，也未执行收集。","boundary":"排除理由来自明示约束，不来自时间数值自动推导；若证据变化则重新比较。"}],"counterexamples":[{"identity":"constructed_boundary","text":"EVSI非负，所以调查不论多贵都值得做。","effect":"非负只针对免费可忽略的信息毛价值，现实净值可能负。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"X与Y分别EVSI为零，联合一定为零。","effect":"异或构造联合可精确知道状态，增益1/2。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"不能求总分，所以不能提出任何偏好。","effect":"可以在明示规范下给供审议的条件偏好，保留冲突而不越权定案。","sourceIds":["theory"]}],"questionAnswers":[{"question":"EVSI证明中最关键的不等式是什么？","answer":"信号后最优动作至少不劣于仍选原a*，再用全期望公式。","basis":"本节原文及上述公开推导"},{"question":"异或例只见X为何无增益？","answer":"Y仍公平，所以θ条件分布仍各1/2；X本身不能提高猜中期望。","basis":"本节原文及上述公开推导"},{"question":"成本0.6时净值是多少？","answer":"毛值0.5减成本0.6为−0.1，前提成本和效用可比。","basis":"本节原文及上述公开推导"},{"question":"统一比较卡为何不必统一总分？","answer":"维度可能不可通约或受硬权利约束，统一记录即可，权衡需额外公开理由。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-10/figures/section-12-10.png","alt":"路径与目标，保护／分配／溢出，不强行求总分；信息价值，可否改变有依据选择，理解价值另保留；可逆／资源／权限，停止／回滚／补救，须核真实条件；构造：只见X或Y，异或θ仍均匀，各自EVSI=0；联合见X与Y，可确定θ=X异或Y，EVSI=0.5；同尺度成本0.6，净值0.5−0.6=−0.1，毛值不等净值。下排为公平独立比特的数学构造；信息价值公式不产生现实数据采集权限。","caption":"下排为公平独立比特的数学构造；信息价值公式不产生现实数据采集权限。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。后续可逐行展开四种比特组合，保持概率、成本和效用假设可见。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节的形式信息价值以完整证明和可枚举构造检验最直接；无现实项目的完整效用、概率、成本与权限材料，不伪造经验EVSI。"},"openQuestions":["实际效用与概率是否可接受、隐私成本能否比较、信息采集是否获准，都需另作材料与程序判断。"],"taskId":"S-12-10","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2582—2612行；每节精确范围见sourceRefs","claim_support":["12.10：术语、合同、论证责任和原文边界；不据此认证经验事实","12.10.1：术语、合同、论证责任和原文边界；不据此认证经验事实","12.10.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"connections","title":"原书F3与联合资源反例","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.18.3第993—996行；附录C.12第4515—4521行","claim_support":["共同动作交集的必要充分性、单轮确定性边界及共享容量反例"],"limits":["形式命题不证明现实集合成员资格、资源、授权或执行已发生。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-10/lecture.md","sourcesPath":"/reading-assets/S-12-10/sources.json","sourceSlicePath":"/reading-assets/S-12-10/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-10/diagrams.md"},"12.10.1":{"title":"12.10.1　从可识别答案到可行选择","lead":"不知道究竟处于哪种状态，不一定什么都不能做；但每种状态各自有办法，也不保证你现在选得出一个共同合格的办法。","explanation":["原文定位：第2601—2606行；原文锚点 section-12-10-1；短引文：‘识别全部状态不是有限行动的普遍前提’。本题源切片逐字附后，讲解与原文分开。","令当前材料相容的可信状态集合非空。对每个状态z，A_ok(z)不是随意想出的动作列表，而是已按公开目标、保护底线、资源与有效权限确定的合格动作集合。否则形式交集即使非空，也只是纸面动作，不是现实可行性。","有限单轮确定性选择中，共同交集非空，意味着至少存在一个动作，在所有已列相容状态里均合格。于是可比较这些共同动作，不必先知道实际是哪一状态。这是保留未知仍可有限行动的正面条件，不要求为了完美认知而无限等待。","交集为空时，每个集合各自非空也不够：知道z1会选左，知道z2会选右，但当前表示不区分z1、z2，就不能在单次确定性规则下保证选对。可检查补证、等待、缩小目标或已有独立依据的保护动作是否改变条件；不能假定这些选择自动可用。","反过来，问题有充分答案也不保证能行动。即便已识别状态z1，若所需资源不足、保护不合格或权限缺失，A_ok(z1)仍可为空。识别、可计算、可访问、能实施、有资源与有权采用属于不同职责，不可把正确答案当通行证。","这个条件只覆盖已列可信状态和约束，不保证遗漏状态不会出现。它也不宣布最坏情形准则唯一理性：有依据的概率、风险容忍、随机或序贯策略可以产生其他规则，但必须明示自己的目标和条件，不能把本单轮确定性结论无边界推广。","本节与§4.18.3（993—996行）及附录C.12（4517—4521行）的F3一致。比较卡先固定何为合格，本节证明信息不足时能否有共同动作；下一节再检验多个共同或各自可行动作会不会争用同一资源。"],"distinctions":[{"leftTitle":"各状态各有办法","leftText":"每个A_ok(z)分别非空。","rightTitle":"共同有一个办法","rightText":"所有集合交集非空，逻辑更强。"},{"leftTitle":"状态充分识别","leftText":"知道当前状态是哪一个。","rightTitle":"行动可行","rightText":"资源、保护和权限也须成立。"},{"leftTitle":"共同合格","leftText":"对已列全部相容状态过约束。","rightTitle":"现实绝对安全","rightText":"未列状态和条件变化仍可能出现。"},{"leftTitle":"单轮确定性条件","leftText":"一个动作对所有列明状态合格。","rightTitle":"所有决策理论","rightText":"概率、随机与序贯策略有各自分析。"}],"boundaries":["不得先把无权限动作放进合格集合，再用交集证明自己有权。","空交集不证明任何形式的行动或策略都不可能。","追加观察可能有费用、风险与权限条件，不能当免费自动可得。","非空交集仅证明有共同候选，不保证已选出唯一最优动作或已经执行。"],"questions":["两个集合{左、保全}和{右、保全}交集是什么？","F3证明是否验证实际授权？","唯一知道z1为何仍可能不能行动？","非空交集是否表示唯一最优？"],"diagramPath":"/reading-assets/S-12-10/figures/section-12-10-1.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.10.1","start_line":2601,"end_line":2606,"startLine":2601,"endLine":2606}],"outputId":"section-12-10-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["列当前材料相容的非空可信状态集合，不把未知状态声称穷尽现实。","逐状态先核目标、保护、资源、权限，形成A_ok。","计算共同交集并公开成员或空集，分别说明其有限含义。","交集非空可比较共同选项；为空则核补证、缩小任务或其他独立策略条件。","保持单轮确定性适用域，不排除另有根据的概率与序贯方法。"],"teachingExamples":[{"title":"形式证明：共同动作与交集非空等价","text":"必要性：若仅依据当前表示y选择同一个动作a，且对每个相容状态z合格，则a∈A_ok(z)对所有z成立，故a属于交集。充分性：若交集非空，取其中任意a，则它对每个z都合格，选择不需分辨实际z。证明只用集合定义，并不提供各集合在现实中合格的证据。","assumptions":"有限单轮确定性任务，非空观察类和已确定的合格集合。","boundary":"未证明序贯、随机或风险容忍策略的必要充分条件；也未认证现实权限。"},{"title":"教学构造：未知状态下仍有共同保护选项","text":"虚构z1合格集合{左、保全}，z2为{右、保全}，保全假设已具备本次资源、保护和有效授权，交集{保全}。可在不知道z1还是z2时比较并选择保全。若保全权限到期被移出两集合，剩{左}与{右}，交集空；此时不能沿用上一版本的可行结论。","assumptions":"动作名称、状态和授权均为形式题设，无实际保全操作。","boundary":"保全不是天然合法的神奇动作，前提失效需重新核。"},{"title":"形式构造：知道答案也可能没有可行动作","text":"材料已唯一识别状态z1，但所需动作左要容量2，而当前只有1，其他动作违反题设保护约束。A_ok(z1)=空，因此状态完全可识别而本任务不可执行。若新增容量真实到位并满足权限，才可能形成新合格集合。","assumptions":"容量和约束人为给定，无现实资源申请。","boundary":"知道缺多少资源不等新增资源已获得，也不等旧截止自动延长。"}],"counterexamples":[{"identity":"constructed_boundary","text":"每个状态都有一个动作，所以现在一定选得对。","effect":"{左}与{右}分别非空但共同交集空。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"不知道全部状态，所以任何有限行动都必须暂停。","effect":"若有已经合格的共同动作，识别全部状态不是必要条件。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"交集空证明随机和序贯策略都无用。","effect":"本条件不涉及它们，须按各自目标和约束另分析。","sourceIds":["theory"]}],"questionAnswers":[{"question":"两个集合{左、保全}和{右、保全}交集是什么？","answer":"{保全}，但保全必须已经满足资源、保护与权限。","basis":"本节原文及上述公开推导"},{"question":"F3证明是否验证实际授权？","answer":"不验证，授权等条件是A_ok资格的前置证据责任。","basis":"本节原文及上述公开推导"},{"question":"唯一知道z1为何仍可能不能行动？","answer":"若资源或权限不足，A_ok(z1)仍为空。","basis":"本节原文及上述公开推导"},{"question":"非空交集是否表示唯一最优？","answer":"不表示，只证明共同合格动作存在，多个选项仍需比较。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-10/figures/section-12-10-1.png","alt":"状态z1，合格：左、保全；共同交集，{保全}，未知仍可有限选择；状态z2，合格：右、保全；删去未获准保全，z1仅{左}；交集为空，单轮确定性保证不足，另核信息或策略；删去未获准保全，z2仅{右}。形式构造；所有合格集合须先核资源、保护和有效权限，图不创造保全授权。","caption":"形式构造；所有合格集合须先核资源、保护和有效权限，图不创造保全授权。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。可切换合格集合并展示交集，但必须同时展示每个资格的证据与有效期。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节是形式命题，完整集合证明及边界构造优于用不完整现实材料冒充权限与可行性认证。"},"openQuestions":["实际状态集合覆盖、合格约束与权限仍需逐案证据，当前仅验证形式关系。"],"taskId":"S-12-10","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2582—2612行；每节精确范围见sourceRefs","claim_support":["12.10：术语、合同、论证责任和原文边界；不据此认证经验事实","12.10.1：术语、合同、论证责任和原文边界；不据此认证经验事实","12.10.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"connections","title":"原书F3与联合资源反例","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.18.3第993—996行；附录C.12第4515—4521行","claim_support":["共同动作交集的必要充分性、单轮确定性边界及共享容量反例"],"limits":["形式命题不证明现实集合成员资格、资源、授权或执行已发生。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-10/lecture.md","sourcesPath":"/reading-assets/S-12-10/sources.json","sourceSlicePath":"/reading-assets/S-12-10/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-10/diagrams.md"},"12.10.2":{"title":"12.10.2　多项方案的联合可行性","lead":"每项任务都说自己只需要一份资源，最后可能把同一份资源承诺了两次。联合可行性必须把容量、依赖、人员、停止能力和截止时间放进同一张约束表。","explanation":["原文定位：第2607—2612行；原文锚点 section-12-10-2；短引文：‘二者单独可行、联合不可行’。本题源切片逐字附后，讲解与原文分开。","单项可行只证明该动作单独使用条件时可完成，不证明多项同时实施时仍有足够容量、预算、人员或停止通道。不同部门各自通过评估，若占用同一资源，就需再做联合约束检验。资源名称不同也可能底层依赖同一人或同一平台。","最小反例是两项单位任务各需完整本期且都须本期结束前完成，本期容量只有1。任一任务单独占1≤1可行；联合需2>1不可行。下期有新增容量不改变本期截止，不能把以后做完写成原任务按时完成。","增加同期容量可改变约束；有依据且获准延后一个任务截止，也可形成新可行方案，但应保留原合同与修订身份。如果已经错过旧期限，即使后续追补成功，旧的未按时完成记录仍在。延期本身的损害和受影响者保护不能被排程数学抹去。","资源排程还需连接任务依赖。核实前提、取得授权、执行和起效若具有串行依赖，就不能凭工具并发把它们视作同时完成。真正独立的读取或任务可并行，但共同写入对象、共享容量、版本前提和冲突都要有处理规则。","停止能力也是资源：同一个人员或通道如果不能在关键窗口同时响应多个停止请求，不能把每个方案的单独停止承诺直接拼成联合可停止。回滚、补救和监测责任也可能争用同一资源，必须连同正常执行一起核。","任务完成终点要到所承诺的受影响者与保护结果。首节点完成、请求发送或界面成功不等最后一位已获保护；时间和覆盖必须同时检查。此处与12.6端到端时钟相接，并由附录C.12第4515行的单位容量反例直接支持形式边界。"],"distinctions":[{"leftTitle":"单项可行","leftText":"动作独自使用资源可满足约束。","rightTitle":"联合可行","rightText":"所有动作同一排程下同时满足共享约束。"},{"leftTitle":"后续补足资源","leftText":"未来可做更多。","rightTitle":"原截止已满足","rightText":"需要当时就有足够资源并实际完成。"},{"leftTitle":"独立并行","leftText":"没有必须先完成的依赖且资源足够。","rightTitle":"串行强行并发","rightText":"前提尚未成立就执行下游。"},{"leftTitle":"执行能力","leftText":"正常动作有资源。","rightTitle":"停止与补救能力","rightText":"异常同时发生也要资源和真实机制。"}],"boundaries":["联合可行性证明依赖题设需求、容量及期限真实，数学本身不认证这些输入。","延期须有依据与有效程序，不得由模型自行重写合同。","共享资源不只机器容量，人员、预算、停止通道也可能瓶颈。","排程可行不等已经执行或受影响者已经得到承诺保护。"],"questions":["需求各1、容量1时为何单项可行而联合不可行？","把B合法改到第二期后什么成立？","联合比较为何要列停止通道？","核验、授权、执行能否为加速全部同时跑？"],"diagramPath":"/reading-assets/S-12-10/figures/section-12-10-2.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.10.2","start_line":2607,"end_line":2612,"startLine":2607,"endLine":2612}],"outputId":"section-12-10-2","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["列每项动作的资源占用、依赖、截止和真正完成终点。","找出共同底层资源、人员与停止通道，统一核每个时段容量。","逐项可行后另查联合不等式，发现冲突不得重复承诺。","同期扩容或合法调整条件产生新方案，旧期限结果不回改。","核串行关键路径、末端覆盖及停止补救能力，不以首节点完成代替整体完成。"],"teachingExamples":[{"title":"数学构造：两项本期任务争用一个容量","text":"任务A、B各需本期完整1单位容量，截止都为本期末，容量C1=1。分别看，dA=1≤1、dB=1≤1；联合dA+dB=2>1，无法同时按时完成。若本期容量改为2，则需求2≤2可排；若仅第二期容量增至2但两个原截止不变，仍不能满足本期任务。","assumptions":"离散单期、单位不可分工作量，容量与截止人为给定。","boundary":"可分割、不同工期或抢占规则会改变模型，但不允许在原模型中偷偷引入这些条件。"},{"title":"数学构造：合法新截止可形成新排程","text":"沿前例，假设有效程序把B的新截止改至第二期末，并且C1=C2=1。安排A第一期、B第二期，各期占用1且分别符合新截止。新合同可行不表示旧的双任务本期截止合同已完成；若修改发生前已逾期，旧逾期也不消失。","assumptions":"延期依据与授权在构造中明确假设成立，没有真实延期操作。","boundary":"现实延期可能伤害某方，仍须其适用保护、权利、程序和补救判断。"},{"title":"教学构造：停止承诺也会资源冲突","text":"虚构两项试点同时运行，各自要求收到停止信号后1分钟内由同一监督员完成一次需整整1分钟的人工停机；若两信号同时到达，且无其他可用停止通道，一位监督员不能同时完成两次。每项单独有可停止性，并不证明联合运行同样满足停止期限。","assumptions":"人力、操作时间与并发信号全为教学构造，不描述任何真实安全系统。","boundary":"真实系统可能有独立自动停止或多人支持，须实际核验而非默认存在。"}],"counterexamples":[{"identity":"constructed_boundary","text":"A和B都通过单项资源审查，所以一起实施也通过。","effect":"共享资源可能被重复承诺，需统一排程核约束。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"下期加容量就能证明本期没错过截止。","effect":"未来资源不能补回过去期限，最多构成追补与新方案。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"每个试点都有同一监督员，联合停止就有保障。","effect":"同一监督员可能无法同时履行多个短时停止承诺。","sourceIds":["theory"]}],"questionAnswers":[{"question":"需求各1、容量1时为何单项可行而联合不可行？","answer":"单项1≤1，联合2>1，两个原截止相同不能跨期挪用。","basis":"本节原文及上述公开推导"},{"question":"把B合法改到第二期后什么成立？","answer":"新合同在每期容量1下有排程，不代表旧合同已按时完成。","basis":"本节原文及上述公开推导"},{"question":"联合比较为何要列停止通道？","answer":"故障同时发生时也会争用人员和能力，单项承诺不保证联合达标。","basis":"本节原文及上述公开推导"},{"question":"核验、授权、执行能否为加速全部同时跑？","answer":"若有前后依赖就不行；只有独立环节且资源与权限允许时才可并行。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-10/figures/section-12-10-2.png","alt":"任务A本期需1，单项1≤1：可行；本期共享容量1，A＋B需求2>1，联合不可行；任务B本期需1，单项1≤1：可行；同期容量增至2，可形成新排程；只加下期容量，不补回本期旧截止；合法改B新截止，可另排第二期，旧记录仍保留。单位任务与容量均为形式构造；资源、期限、保护与有效权限在现实中须分别核实。","caption":"单位任务与容量均为形式构造；资源、期限、保护与有效权限在现实中须分别核实。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。后续可按期移动任务块，若改变截止必须显式建立新合同，不能让旧任务悄然变成按时。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节的共同容量反例可由公开约束直接证明；未取得现实资源与期限档案，不虚构组织实际违约或保护失败。"},"openQuestions":["真实任务的可分割性、并行性、资源容量、停止时延与有效截止仍须证据。"],"taskId":"S-12-10","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2582—2612行；每节精确范围见sourceRefs","claim_support":["12.10：术语、合同、论证责任和原文边界；不据此认证经验事实","12.10.1：术语、合同、论证责任和原文边界；不据此认证经验事实","12.10.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"connections","title":"原书F3与联合资源反例","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.18.3第993—996行；附录C.12第4515—4521行","claim_support":["共同动作交集的必要充分性、单轮确定性边界及共享容量反例"],"limits":["形式命题不证明现实集合成员资格、资源、授权或执行已发生。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-10/lecture.md","sourcesPath":"/reading-assets/S-12-10/sources.json","sourceSlicePath":"/reading-assets/S-12-10/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-10/diagrams.md"},"12.11":{"title":"12.11　行动上限与信息性试验","lead":"为了学习而做的事仍然会影响别人。试验规模小、证据好或动机善意，都不能单独决定行动上限；权限、保护和真正可逆性必须一起成立。","explanation":["原文定位：第2613—2626行；原文锚点 section-12-11；短引文：‘信息性试验不是免责任的“小动作”’。本题源切片逐字附后，讲解与原文分开。","行动上限由证据、可逆性、权限与保护共同约束，不能把它们合成一个分数后用强项抵销硬缺口。证据很强但没有权限，仍不能自行执行；授权清楚但保护失败，也不能照常推进。证据弱、风险高、不可逆或权限不足时，可转向有依据的观察、缩小动作、改善信息、保护、申诉或当前不行动。","原表第一类：证据弱但损害低、可逆且授权清楚，可以考虑小范围观察或试探，这只是上限示例而非自动许可；仍要说明学习问题、对象、受影响者和保护。第二类：证据中等、损害可控且能回滚，可考虑分阶段行动和强停止门，不能把“中等”作为无需说明的标签。","第三类证据强但权限不足，应提交有权限主体，不自行执行。第四类证据强但不可逆且保护未满足，应暂停并补足程序与保护，不能用“已确定有效”豁免低权力位置。第五类紧急安全威胁只允许依外部已有的紧急授权作最小保护动作并尽快复核；紧急二字不由模型自造权限。","信息性试验必须说明试验对象、受影响者、最小范围、可逆性、停止、数据用途和补救。还应把待区分机制、成功或失败判据、观察期限及后续扩张是否重新审批写明，否则所谓学习可能只是包装既定动作。试验不是因为能产生数据就当然值得做。","不能把低权力位置当校准材料。谁承担暴露、失败和记录风险，谁有权拒绝，谁获得收益，谁可申诉与撤回，都须可见。形式勾选同意若伴随失去关键资源、报复或无法退出，不构成这里所要求的真实自愿。","可逆须分清对象状态、信息传播和后果。恢复一个设置不保证已经泄露的信息被收回，也不保证错过机会或造成损害被修复。回滚能力还需执行者、资源、时限、验证与补救，而不只一句“随时可以撤销”。","试验范围应以足以回答所问问题的最小相称动作构成，且不得低于保护要求。若缩小后根本不能区分机制，应诚实说无识别力，不拿不安全的大规模扩张补救方法缺陷；也可改用模拟、既有资料或不实施，但替代方法的支持上限须明确。","停止门要事前定义并真实可触发。监测异常、退出失败、权限到期、资料失真或保护底线受损时，依适用程序停止相应部分并核后果。试点成功不自动授权推广，信息用途扩大、对象变化或期限延长都需重核条件。"],"distinctions":[{"leftTitle":"规模小","leftText":"某一量如人数或时长较少。","rightTitle":"风险低可逆","rightText":"须核影响性质、传播、退出和补救。"},{"leftTitle":"证据强","leftText":"描述或效应判断有较好支持。","rightTitle":"权限充分","rightText":"主体对特定动作范围有独立有效依据。"},{"leftTitle":"设置可恢复","leftText":"技术参数可以改回。","rightTitle":"后果可逆","rightText":"信息、机会和伤害也须分别看。"},{"leftTitle":"真实自愿","leftText":"可以理解、拒绝、退出而不遭不当惩罚。","rightTitle":"形式同意","rightText":"一次勾选或沉默不自动满足。"},{"leftTitle":"试点通过","leftText":"限定范围和目标得到支持。","rightTitle":"推广授权","rightText":"对象、规模、期限和用途改变须重核。"}],"boundaries":["本节表格是行动上限示例，不构成任何实际试验审批。","紧急威胁不使AI或分析者获得本来不存在的权限。","收集更多数据也可能造成不可逆伤害，不能拿信息价值豁免保护。","真实人体或读者试验未执行，教学方案不能写成实测成效。"],"questions":["四项中J为假而其余为真能否执行？","试点成功是否自动扩大到全部人群？","紧急情况下谁给权限？","隔离副本草案能证明现实等待下降吗？"],"diagramPath":"/reading-assets/S-12-11/figures/section-12-11.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.11","start_line":2613,"end_line":2626,"startLine":2613,"endLine":2626}],"outputId":"section-12-11","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["明确证据支持程度、风险与可逆性的各自依据，不用总分抵销权限或保护。","选择与条件相称的输出上限，缺执行权限时移交而非自行行动。","为信息性试验登记对象、学习目标、最小范围、数据用途与受影响位置。","核真实拒绝退出、停止、回滚及补救能力，保护不能因试验缩减。","把结果限于原范围，推广或用途改变另审，紧急情形只依外部有效权限。"],"teachingExamples":[{"title":"教学构造：一个只在隔离副本上运行的试验草案","text":"虚构系统拟比较两种队列排序。草案限定10条人工生成且无个人信息的任务、隔离环境、两小时、只读源数据，不连生产执行器。预登记比较平均等待和最大等待；若出现生产连接、真实个人数据、日志缺失或到期即停止。结果只评模拟规则，不认证真实服务效果。由于没有实际授权记录和运行，此处仅为可审议设计，不宣称已执行或获批。","assumptions":"对象与任务全是教学假设，无真实用户资料；隔离、无个人信息亦为拟议条件，未实测。","boundary":"即使设计低风险，实施仍需环境与权限核验；真实生产推广需重新评估人群、保护与资源。"},{"title":"形式构造：强证据不能补齐权限缺口","text":"设证据支持E、可逆R、权限J、保护P均为适用硬条件，行动资格要求E且R且J且P。即使E=真、R=真、P=真，只要J=假，合取为假。将四项平均为0.75再设阈值0.7，会错误通过本应由权限否决的动作。此算式仅说明硬门不能被平均。","assumptions":"真假值与门逻辑是明确构造，不把现实证据强度压成二元事实。","boundary":"实际判断可有未知与不适用状态，必须给理由；本例不提供一个足以覆盖所有任务的万能评分系统。"},{"title":"教学构造：恢复按钮不等收回披露","text":"虚构试点把一条敏感记录展示给外部观看者，界面随后删除显示。显示状态恢复不保证观看者忘记、截图消失或后续影响消除，因此不能仅以可删界面称试点完全可逆。","assumptions":"仅为信息传播边界构造，没有真实敏感资料被披露。","boundary":"不推定所有信息试验都不可做；需要事前限制暴露、有效同意及相称保护，不能事后用按钮代替补救。"}],"counterexamples":[{"identity":"constructed_boundary","text":"只试一个人，所以不需要保护与退出。","effect":"人数少不使该人权利变小，影响可能仍不可逆。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"证据非常强，可以先做再找有权的人签字。","effect":"权限是独立门，不能靠预测质量倒补。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"界面能恢复，所以所有后果都可回滚。","effect":"信息传播与已发生损害需独立核验和补救。","sourceIds":["theory"]}],"questionAnswers":[{"question":"四项中J为假而其余为真能否执行？","answer":"在本构造硬门下不能，平均分无权抵销权限缺口。","basis":"本节原文及上述公开推导"},{"question":"试点成功是否自动扩大到全部人群？","answer":"不自动，规模、对象、用途与期限改变要重核保护、证据和授权。","basis":"本节原文及上述公开推导"},{"question":"紧急情况下谁给权限？","answer":"来自适用外部紧急授权，本节或模型不能自行签发；行动限最小保护并尽快复核。","basis":"本节原文及上述公开推导"},{"question":"隔离副本草案能证明现实等待下降吗？","answer":"不能，未执行；即使未来模拟通过，也只支持相应模型条件。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-11/figures/section-12-11.png","alt":"证据与风险，支持什么、缺什么，高置信不造权限；权限与保护，对象／范围／期限，真实拒绝与退出；可逆与停止，状态回滚≠后果消失，补救须可达；拟议最小试验，对象／问题／指标，数据用途／期限；任何硬门缺失，缩小、暂停或移交，不能用平均分补齐；结果只在原范围，推广与用途改变，重新核条件。这是未执行的教学设计与边界图；紧急保护也须依外部有效授权。","caption":"这是未执行的教学设计与边界图；紧急保护也须依外部有效授权。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。后续可显示每个门的证据与未知状态，不用一个总百分数自动通过试验。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节重点为试验资格与责任边界；没有完整现实试验授权及受影响者资料，采用明确未执行的草案和逻辑构造，不冒充人体或系统实验。"},"openQuestions":["任何真实试验仍需核权限、保护、退出、环境隔离、数据用途与停止资源；当前无实施授权或实际运行结果。"],"taskId":"S-12-11","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2613—2626行；每节精确范围见sourceRefs","claim_support":["12.11：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-11/lecture.md","sourcesPath":"/reading-assets/S-12-11/sources.json","sourceSlicePath":"/reading-assets/S-12-11/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-11/diagrams.md"},"12.12":{"title":"12.12　结果回写与模型学习","lead":"学习不是把旧预测改得像早就知道答案。真正的更新保留原判断、实际结果、偏差及后果，再说明下一版改变了什么、凭什么改变。","explanation":["原文定位：第2627—2632行；原文锚点 section-12-12；短引文：‘前瞻和选择的结果回写只能追加’。本题源切片逐字附后，讲解与原文分开。","结果回写只追加，原目标、概率或排序、期限、路径条件和选择理由保持可追踪。新增记录要关联原预测与原行动合同，写结果观察时间、来源、实际结果、路径匹配、校准指标和简单基线比较；更正错误可以形成有效新版本，但不能让旧错误从历史消失。","回写还包括意外效应、受影响位置复核、模型更新、断言降级、退役变量或路径，以及下一次复核。没有变化也须区分是稳定证据、尚未到期、资料缺失还是未执行监测，不能用空白代替状态说明。","行动结果不能只按主目标评。局部等待变短可能伴随另一个圈层负担增加；总体成本下降可能把成本转给无法退出者；短期效果好可能遮蔽长期损害。副作用、跨圈层溢出、分配、申诉与长期时钟都要进入回写，不能等它们影响主指标才承认。","一次成功只支持相应对象、条件与时窗，不能宣布机制普遍成立。一次失败也可能来自实际执行偏离，但执行偏离要有独立过程记录，并按冻结合同判断它究竟使哪条结论失败或仍未检验。不能在看到坏结果后临时加一个“执行不到位”把模型从一切反例中保护起来。","须区分三种问题：预测实际结果的合同有没有得分失败；在明示条件成立时的机制预测有没有被检验；已经选择的行动是否依要求发生。这些问题可同时有不同状态。实际结果预测失败不能因某条件未实现被抹除；条件机制尚未检验也不等被证实。","模型学习应指出具体变更，如参数重估、某机制降级、某变量退出、适用域缩小或路径退役，并绑定支持材料与验证计划。用同一批结果调参后在同一批上变准，只是样本内改善，不能当新版本已具未来预测增益；后续评价仍需按相应设计冻结。","若原数据发生更正，应追加更正理由、来源与影响范围，说明哪些指标和下游结论需重算。保留原评分及更正后评分的版本关系，不让读者误以为从未出错。数据更正和模型修订是不同变化，不应混成一次无法回溯的“更新”。"],"distinctions":[{"leftTitle":"追加更新","leftText":"保留旧判断与结果，建立新版本。","rightTitle":"覆盖历史","rightText":"用新答案抹掉旧失败。"},{"leftTitle":"执行偏离","leftText":"有过程材料证明未按原条件实施。","rightTitle":"事后救援","rightText":"没有依据却为坏结果临时加免责条件。"},{"leftTitle":"样本内调参更好","leftText":"对已看到的结果拟合更近。","rightTitle":"未来增益已证明","rightText":"还需相应独立或前瞻评价。"},{"leftTitle":"主目标成功","leftText":"预先指定指标达到条件。","rightTitle":"行动整体合宜","rightText":"副作用、分配、保护和长期影响仍须核。"},{"leftTitle":"条件未检验","leftText":"必要条件未发生而不能检验该条件断言。","rightTitle":"模型正确","rightText":"缺乏反证不能当正证。"}],"boundaries":["旧结果必须保留；更正标签也不能让来源错误历史消失。","执行解释须由冻结合同和过程记录支持，不能随结果任意改变模型。","单次好结果不认证普遍机制，调参后重算不自动构成独立验证。","受影响位置的不良后果不能因主目标改善被删去。"],"questions":["构造A误差为何4而B仍未检验？","P与Q的MAE各是多少？","更正标签时是否只保留最新分数？","模型学习最少还需写什么？"],"diagramPath":"/reading-assets/S-12-12/figures/section-12-12.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.12","start_line":2627,"end_line":2632,"startLine":2627,"endLine":2632}],"outputId":"section-12-12","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["关联冻结预测与选择合同，追加真实结果的时间、来源、标签状态和路径匹配。","按原口径计算表现与基线比较，保留失败和未决。","核实际执行与条件成立证据，区分预测、机制与执行三类责任。","逐位置登记副作用、溢出、分配、申诉和长期后果。","以新版本写明模型变更、降级或退役及下一次复核，拒绝样本内自证。"],"teachingExamples":[{"title":"教学构造：实际结果预测失败与条件机制未检验可以并存","text":"虚构登记A预测两小时末积压4，并假定每小时处理3；登记B另明确为“若每小时实际处理3且到件2，则从6降到4”的条件机制断言。期末完整日志表明实际处理仍为1、到件2，终点8。A的实际结果预测误差|4−8|=4；B的处理条件未发生，因此这次未检验B的条件效应。不能把B未检验写成正确，更不能抹去A误差。","assumptions":"两份合同、日志与数字均为教学构造，无真实系统数据。","boundary":"若A本来也是明确条件断言，应按其原合同评价；不能事后在A和B身份间切换。"},{"title":"数学构造：追加记录同时保留模型与基线","text":"构造三次冻结点预测P=(5,7,9)，简单基线Q=(6,6,6)，实际Y=(6,8,10)。P的MAE=(1+1+1)/3=1，Q的MAE=(0+2+4)/3=2，样本内比较差为1。看到结果后新版本把三项各加1，在同三项上误差0；这不证明未来MAE为0。应保存P/Q原预测、Y及各误差，另登记新版本及下一批评价计划。","assumptions":"三组数字全为数学构造，未训练模型或开展真实预测实验。","boundary":"三项支持极有限，不能由MAE差宣称跨场景稳定优越；新版本不能拿已看标签充独立测试。"},{"title":"教学构造：主指标改善仍要记录成本转移","text":"虚构服务调整让A组平均等待从10降至7，但B组额外承担每人2小时的未补偿工作，且其中有人不能退出。回写须同时保留A组改善与B组负担、表达和申诉状态，并核规范与保护条件，不得只发“等待降低30%”。","assumptions":"群体、时长与负担人为设定，没有真实劳动或服务事件。","boundary":"无法由这些数字单独断言现实违法或选择合宜；规范约束与有效制度另核。"}],"counterexamples":[{"identity":"constructed_boundary","text":"新模型在旧数据上零误差，因此未来已可靠。","effect":"已见标签可导致样本内拟合，须另评未来表现。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"失败一定是执行者问题，模型不可能错。","effect":"执行偏离要有独立记录，模型条件、映射和估计也可能错。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"主目标改善，其余影响不属于模型结果。","effect":"实际选择的副作用、溢出、分配与申诉都须回写。","sourceIds":["theory"]}],"questionAnswers":[{"question":"构造A误差为何4而B仍未检验？","answer":"A预测实际4而观察8；B明确依赖实际处理3，但记录只有1。两个合同问题不同。","basis":"本节原文及上述公开推导"},{"question":"P与Q的MAE各是多少？","answer":"P为1，Q为2；同三项上的有限差不能保证以后优势。","basis":"本节原文及上述公开推导"},{"question":"更正标签时是否只保留最新分数？","answer":"应追加更正与来源、保存原分数和新分数的版本关系并重核依赖项。","basis":"本节原文及上述公开推导"},{"question":"模型学习最少还需写什么？","answer":"具体改动、依据、降级或退役内容、适用域及下一次复核，而不只写“已优化”。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-12/figures/section-12-12.png","alt":"冻结预测与选择，目标／条件／期限，原版本保留；实际结果追加，观察时间／来源，执行与标签状态；原口径评价，路径／指标／基线，副作用与分配；新版本修改，依据／降级／退役，下一次复核；不覆盖旧失败，不拿执行解释，随意救援模型；同批调参误差0，不等未来误差0，新评价另冻结。图为追加式评价逻辑；教学算例没有真实模型训练、预测或干预执行。","caption":"图为追加式评价逻辑；教学算例没有真实模型训练、预测或干预执行。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。后续可展开旧预测、原评分与更正版本的关联，不能只显示最新最好的一行。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节需要完整冻结预测、实际执行及结果档案；当前未提供此类现实资料，故用可复算构造展示合同和版本责任，不虚构模型验证成果。"},"openQuestions":["实际结果及执行证据尚未给定，不能判定现实模型应更新哪个参数或是否退役。"],"taskId":"S-12-12","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2627—2632行；每节精确范围见sourceRefs","claim_support":["12.12：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-12/lecture.md","sourcesPath":"/reading-assets/S-12-12/sources.json","sourceSlicePath":"/reading-assets/S-12-12/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-12/diagrams.md"},"12.13":{"title":"12.13　一个完整的前瞻—选择示例","lead":"这个公开离职事件是原书贯穿的示例，不是一份已核实的企业调查。本讲继续把它作为教学构造，将条件推演、前瞻登记、规范比较和执行资格逐步接起来。","explanation":["原文定位：第2633—2640行；原文锚点 section-12-13；短引文：‘不能只挑中间某个命中信号宣布成功’。本题源切片逐字附后，讲解与原文分开。","原书§10.11（2195—2202行）建立员工、团队、管理层、家庭照护、职业社群与平台的联合对象；§11.11（2420—2429行）给出事件传播及竞争路径。本节进一步登记三个月目标与方案选择。对象关系只是教学设定；不能由公开离职文本直接诊断人格、读取家人内心或认证圈层增益。","目标可设为未来三个月团队自愿离职是否明显高于历史与同类团队基线，输入截止为公开说明后一周。“明显”必须事前操作化，并说明团队成员分母、观察窗口、何为自愿离职、转岗或裁撤如何分类、缺失怎么处理。原文未给这些具体数值，下面仅作可核的教学补充，不能冒称原文已有统计检验。","简单基线只用历史离职率与工时趋势；多圈层候选增加团队信任、管理回应、职业社群桥接、家庭照护与平台曝光。两者仍应使用同一信息截止、同一目标、同一结果口径和预定评价规则，比较增加对象与信息是否值得，不能让复杂模型偷看期末资料或删除难预测成员。","三条路径保持条件身份：P1外部舆论消退但内部问题持续，需工时与申诉未改善、内部表达风险等支持；P2制度调整并逐步修复，需资源和程序实际执行，信任恢复可能慢于工时；P3职业桥接降低退出成本并出现连续退出，需机会可达与实际桥接。它们可在不同位置并存，不强行当作概率和为1的互斥结局。","早期信号包括实际工时变化、申诉处理、成员可安全表达、招聘与外部机会。反向信号包括政策已发却执行缺失、公众安静但内部沉默增加。沉默本身具有多重解释，须核表达安全与资料形成，不能直接当作满意或恐惧；家庭条件变化也只在有桥接证据时传播到团队判断。","三个月后按冻结目标比较复杂模型和简单基线。中间某次招聘增加、某个帖子热度下降或一个成员转移，可能只支持某条机制的局部环节，不能直接宣布整体前瞻命中。实际结果、缺失、响应制度变化和路径解释应分别追加，模型增益要经可比长期评价。","有限选择进入规范层。本讲公开采用N2保护不降级、N3可纠错、N4不强加无限不可退出承担、N5不以团队存续压倒正当，并以N1阻止解释直接授权。另明确教学目标为减少不可承受负担与改善可申诉性，人员留存只是后果之一，不把阻止任何自愿离职当成目标。","应比较原书七项：维持现状、只做公关、立即资源调整、可逆工时与申诉试点、延迟重大重组以收集信息、允许成员转移、不做结构新增行动但加强保护观察。每项核权限、无法退出者、成本分配、跨圈层声誉和家庭影响、停止与补救。最后一项是“不做结构主行动＋独立保护观察”的组合，不等完全不行动；仍要另保留不新增候选动作的明确基线，并承接已有义务。","在上述教学前提且尚无真实执行授权时，当前分析推荐是优先提交限域工时与申诉改进试点供审议，并暂缓不可逆重大重组；其保护与资源条件未核齐前不得实施。理由是它直接针对所列负担和表达机制，较易监测与改判。推荐不假定试点已安全、自愿或获准，也不预断因果效果。","反方与代价不可省：试点可能让部分人承担额外申诉工作，给出短期改善假象，或在小样本中没有识别力；等待又可能延续伤害。若已有充分证据显示严重持续伤害、既有有效权限与安全资源方案，立即资源保护可能优先；若无法保障拒绝退出和反报复，试点应暂停而转向相称外部复核或保护需求移交；若合格接收方和本人选择成立，转移方案应重新比较。"],"distinctions":[{"leftTitle":"原书贯穿示例","leftText":"用于展示联合对象与流程的教学叙述。","rightTitle":"真实企业案例","rightText":"需要可核来源、事实与授权材料。"},{"leftTitle":"操作性阈值","leftText":"人为事先定义怎样算明显升高。","rightTitle":"统计显著性","rightText":"需要相应模型、检验与不确定性，不能仅靠阈值。"},{"leftTitle":"中间信号支持","leftText":"说明某个路径环节可能成立。","rightTitle":"三个月整体命中","rightText":"须按原目标与基线评价。"},{"leftTitle":"团队留存","leftText":"可观察后果之一。","rightTitle":"阻止自愿离职","rightText":"并非本讲认可的规范目标。"},{"leftTitle":"暂不做结构主行动","leftText":"可能同时有独立保护与观察。","rightTitle":"完全不新增行动基线","rightText":"必须另明确其实际动作与责任。"}],"boundaries":["没有真实员工、公司或家庭资料；不能把本讲称为实际组织调查或预测成功。","新增阈值、比例和方案细节均是教学构造，非原书提供的经验事实。","不把公开沉默直接认作信任恢复，也不把一项局部信号当整体命中。","当前推荐只供审议，任何真实试点、资源调整或人员转移都须独立资格。"],"questions":["构造阈值为什么至少4人？","比例点预测0.25是否是事件概率25%？","当前为何有首选却不执行？","原书最后一种方案是否等于完全不行动？"],"diagramPath":"/reading-assets/S-12-13/figures/section-12-13.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.13","start_line":2633,"end_line":2640,"startLine":2633,"endLine":2640}],"outputId":"section-12-13","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["承接原书教学对象，冻结信息截止、三个月目标与可判定口径。","为简单与多圈层候选采用同目标同截止比较，保留三条路径及相反证据。","观察早期信号但不把中间命中当终点，期末按合同计分并追加。","公开规范与正向目标，完整比较七项及明确基线的分配和保护。","给供审议的首选、落选理由、代价与改判条件，现实采用权限另记。"],"teachingExamples":[{"title":"教学构造：把“明显升高”写成冻结合同","text":"构造t0公开说明，t0后一周为截止并登记，预测窗口为登记后的三个日历月。固定起点20名团队成员为分母，完整追踪其中自愿离职人数，新加入者不入该队列；转岗、裁撤按预定类别分开。设同口径历史三个月率5%、匹配团队率10%，定义同时高出两基线至少10个百分点为本次“明显升高”，即离职率≥20%，对应至少4/20。这是操作性阈值，不是统计显著性检验。任一关键成员结果无法追踪时按预登记缺失规则报告未决或限定范围，不填零。","assumptions":"20人、基线率、阈值和口径均人为构造，无真实人事数据；固定队列假设允许完整追踪。","boundary":"历史与匹配组在现实中是否可比需另核选择、规模、时期与口径，不由命名自动成立。"},{"title":"数学构造：终点评价不能由中途帖子代替","text":"假设两候选都在截止时登记三个月固定队列离职比例点预测，简单基线0.15、多圈层候选0.25；教学期末完整记录5/20=0.25。绝对误差分别0.10和0；按上一构造阈值事件也发生。这里0.15和0.25是离职比例的点预测，不是“事件发生”的概率，不能混用二元Brier。这个单次构造不证明多圈层模型长期有增益，更不证明增加的某个变量是因果。","assumptions":"所有预测和结果均为纸面数值，不曾登记或执行真实三个月预测。","boundary":"中途曝光下降并不进入这个终点评分；如果目标或成员定义变化则须保留原合同并另评。"},{"title":"教学构造：完整方案取舍而不假造执行资格","text":"明确基线C0是不新增候选动作但保留既有工资、维护和保护责任；C1主动维持需额外资源且可能延续负担，暂不首选；C2仅公关若无工时与申诉执行不能满足本讲目标，排除作为唯一方案；C3立即资源调整可能直接减负但当前资源及分配证据不足，保留待核；C4限域工时与申诉试点作为当前供审议首选，须先通过保护、有效退出、独立复核和资源条件；C5延迟重大重组可避免锁定但需限期观察和持续伤害复核；C6允许转移需本人选择、合格承接和对留下者负担审查，当前无承接证据不能写已可执行；C7不做结构新增行动而加强保护观察可作过渡组合，新增保护动作各核独立依据。每项记录成本承担、家庭与职业声誉影响、停止与补救，不仅看留存率。","assumptions":"所有方案为教学构造，首选依据是本讲显式规范和限定证据，不是现实授权或最优性认证。","boundary":"C4若不能真正保护退出者或无识别力，则撤回首选；严重持续伤害或已有有效资源方案会使C3/独立保护优先，必须重新比较。"}],"counterexamples":[{"identity":"constructed_boundary","text":"平台热度下降，所以三个月团队离职前瞻已经成功。","effect":"热度只是中间信号，期末目标和简单基线比较仍待完成。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"员工没离开，所以不存在强制或负担。","effect":"无法退出、资源锁定与表达风险可能同时存在，行为不等同意。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"试点是首选，所以现在就改工时和申诉制度。","effect":"这是供审议偏好，未取得权限与保护不得转成执行。","sourceIds":["theory"]}],"questionAnswers":[{"question":"构造阈值为什么至少4人？","answer":"要同时高出5%和10%各至少10个百分点，较严为20%；固定20人中4/20=20%。","basis":"本节原文及上述公开推导"},{"question":"比例点预测0.25是否是事件概率25%？","answer":"不是，它预测离职比例；事件“比例≥20%”的概率是另一个对象。","basis":"本节原文及上述公开推导"},{"question":"当前为何有首选却不执行？","answer":"明示规范与条件允许提出审议建议，但真实权限、资源、退出与保护尚未核齐。","basis":"本节原文及上述公开推导"},{"question":"原书最后一种方案是否等于完全不行动？","answer":"不等，它是不做结构主行动同时新增保护观察的组合，仍需另列明确基线和各动作依据。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-13/figures/section-12-13.png","alt":"教学对象与截止，公开后一周登记，未来三个月目标；三路径并列，内部持续／逐步修复，外部桥接退出；期末同口径评价，简单与多圈层比较，中途信号不代命中；明确规范与分配，七项＋明确基线，保护与退出须可达；条件首选供审议，限域工时申诉试点，反方／代价／改判；现实执行另核，资源／权限／程序，当前并未实施。全图为原书贯穿示例的教学展开，不是真实公司调查、人员预测或执行授权。","caption":"全图为原书贯穿示例的教学展开，不是真实公司调查、人员预测或执行授权。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。后续可展开各方案理由与改判条件，不默认将首选按钮连接真实组织操作。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"原文是无具体企业身份和一手档案的教学示例，本讲保持该身份并公开补充假设，不将它伪装为真实劳动或组织案例。"},"openQuestions":["实际企业事实、成员口径、同类基线、规范选择与执行授权均未提供；没有真实三个月结果或试点成效。"],"taskId":"S-12-13","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2633—2640行；每节精确范围见sourceRefs","claim_support":["12.13：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"connections","title":"原书公开离职联合对象与级联示例","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§10.11第2195—2202行；§11.11第2420—2429行","claim_support":["本节教学事件的联合对象、双通道、时钟、竞争路径和信号前文"],"limits":["未具名且无现实一手档案的教学叙述，不认证真实人员状态与企业事实。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-13/lecture.md","sourcesPath":"/reading-assets/S-12-13/sources.json","sourceSlicePath":"/reading-assets/S-12-13/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-13/diagrams.md"},"12.14":{"title":"12.14　何时选择不做","lead":"不新增主行动不是责任归零。需要同时问两件事：做下去会不会越界，停在这里又让谁继续受损；答案可能是暂缓主动作，同时保留独立有据的保护和观察。","explanation":["原文定位：第2641—2646行；原文锚点 section-12-14；短引文：‘不做可能是谨慎，也可能是逃避’。本题源切片逐字附后，讲解与原文分开。","支持当前不行动或仅保护性观察的条件有七类：对象和事实不清；行动不可逆且证据不足；权限缺失；保护底板未满足；成本可能转嫁给无法退出者；简单和复杂模型均不能区分路径；现有恢复过程可能被外部干预打断。这些是相称暂停的理由，不是把所有工作一律停掉的万能标签。","每种理由应指出具体阻断哪项动作。对象不清可先核对象；资料缺失可提出最小辨别观察；缺权限可移交适格主体；不可逆和保护缺口可以缩小范围、补程序。独立成立的分析和条件推荐仍可完成，不必因执行未获准就退回空泛问题清单。","不行动需更严格审查的条件同样具体：持续伤害正在发生；不作为强化既得优势；负责主体有明确义务或承诺；低权力位置不能自行退出；延迟造成不可逆锁定；以等证据为由无限推迟。不能只看新增行动风险，而把基线持续后果设成零。","“严格审查”不自动等于授权采取原主动作。可以不做大规模重组，却在独立依据下保障申诉、信息可达、最低保护或临时承接。每个辅助动作也有对象、主体、范围、期限和权限，不能借保护名义偷偷扩大管辖或对他人强制披露。","不行动还应有期限、观察责任、重开条件及受影响者表达渠道。哪些事实会改变暂停意见、何时必须复核、资料仍缺时如何说明下一步，都应具体。若到期又无依据地把期限向后滚，原本合理的等待可能变成免责结构。","现有恢复过程可能被干预打断时，先证明恢复机制和时钟的依据，明确适用范围。不能把短期好转或表面安静直接称自愈，也不能以“别打断恢复”阻止当事人申诉或退出。反向信号出现则重新评价继续等待的代价。","不行动与主行动之外的保护不是逻辑矛盾，因为动作范围不同。准确记录“不实施本次候选重组，继续既有服务并按独立权限增加观察”优于泛称“完全不做”。由谁承担持续保护仍须现实可行，不能把责任默认塞给最无力拒绝的人。"],"distinctions":[{"leftTitle":"谨慎暂缓","leftText":"具体缺口阻断具体动作，附复核条件。","rightTitle":"逃避责任","rightText":"只强调不确定性，不交代持续伤害与义务。"},{"leftTitle":"不做主动作","leftText":"限定一种候选行为暂停。","rightTitle":"停止全部保护","rightText":"既有或独立有据保护不因此取消。"},{"leftTitle":"严格审查不行动","leftText":"认真比较等待的伤害与分配。","rightTitle":"自动批准干预","rightText":"仍需相应权限、保护与程序。"},{"leftTitle":"保护性观察","leftText":"有范围、用途和权限的资料取得。","rightTitle":"无限监视","rightText":"不能因保护名义扩展数据与对象范围。"}],"boundaries":["不行动可能是必要，但不能通过删除受害位置和持续后果来显得无成本。","存在紧迫伤害不让模型自行创造主动作或辅助动作权限。","恢复过程须有依据；沉默和短期好转都不是自动证明。","不能把观察与承接责任单方压给无法退出者。"],"questions":["等待3天每日增加2，新增多少？","不重组同时维持申诉是否矛盾？","哪些情况使等待更需审查？","发现恢复迹象就一定不干预吗？"],"diagramPath":"/reading-assets/S-12-14/figures/section-12-14.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.14","start_line":2641,"end_line":2646,"startLine":2641,"endLine":2646}],"outputId":"section-12-14","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先写清拟暂停的具体主动作和支持暂停的条件。","同步评价不新增动作的基线路径、持续伤害及既有义务。","识别无法退出和承担集中的位置，严格审查等待代价。","必要保护、申诉或承接各自核独立依据，不用紧迫感补造权限。","设有时限的观察、重开触发与责任，追加复核而不无限拖延。"],"teachingExamples":[{"title":"教学构造：暂缓不可逆主动作，保留有据保护","text":"虚构组织拟整体关闭服务点，但对象需求资料不完整且关闭难逆，故当前分析支持暂缓关闭。与此同时，已有服务承诺仍须按其自身条件履行；若申诉机制有有效权限，可继续接收和独立复核。是否新增临时服务另查资源和授权。这个组合不是“先关再补”，也不是“什么都不做”。","assumptions":"组织、关闭方案、既有承诺与权限均为教学条件，无现实服务或法律事实。","boundary":"不提供法律意见或确认真实义务；现实需核承诺内容、有效期限、主体与承接能力。"},{"title":"数学构造：等待成本不是零","text":"虚构一个被承认的损害指标，每等待一天增加2单位。若等待信息3天、期间条件不变，则累计新增6单位；若候选行动不可逆且可能产生另一种未量化损害，不能只拿6作自动执行理由，而应把两类风险及权利、权限并列比较。若独立有据的临时保护使每日新增降至0.5，则同三天新增1.5，但其成本与承担者也要登记。","assumptions":"损害单位、线性累计及保护效应全部人为设定，未进行实际干预。","boundary":"不同伤害若不可通约不应强行相减，未知风险不能按零处理，也不能从正数损害推出任意动作有权。"},{"title":"教学构造：等待必须有重开条件","text":"构造记录为：暂不启动结构重组，7天内收集既有流程的同口径资料；指定已有权限的责任角色核验，若保护底线受损、既有服务中断或第7天仍缺关键材料，则立即重开相应审议并说明保护承接。资料收集范围不含未经同意的私人家庭信息。","assumptions":"时间、责任和触发均为教学设计，未执行真实监测或分派人员。","boundary":"真实角色须有时间、能力、权限与接受责任；触发审议不等批准重组。"}],"counterexamples":[{"identity":"constructed_boundary","text":"没有新动作就没有任何责任和成本。","effect":"既有义务、自然变化和持续伤害仍在，须同窗核算。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"既然持续伤害存在，分析者便可执行任何保护措施。","effect":"保护也需相称动作、独立权限和责任，不能任意扩张。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"每周再等一周，总可以称证据审慎。","effect":"若无新依据且延迟代价持续，滚动拖延须接受严格复核。","sourceIds":["theory"]}],"questionAnswers":[{"question":"等待3天每日增加2，新增多少？","answer":"构造条件下6单位；它说明基线有代价，不单独授权行动。","basis":"本节原文及上述公开推导"},{"question":"不重组同时维持申诉是否矛盾？","answer":"不矛盾，动作范围不同，各自按既有或独立有效依据运行。","basis":"本节原文及上述公开推导"},{"question":"哪些情况使等待更需审查？","answer":"持续伤害、义务或承诺、无法退出、优势固化、不可逆锁定及无限拖延。","basis":"本节原文及上述公开推导"},{"question":"发现恢复迹象就一定不干预吗？","answer":"不一定，需核恢复机制与时钟，保留反向信号及申诉退出权利。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-14/figures/section-12-14.png","alt":"为什么先不做？，事实／权限／保护缺口，不可逆或外部化风险；等待会发生什么？，持续伤害／锁定，无法退出与既有义务；逐项相称判断，主动作可暂缓，保护责任仍要核；观察与重开条件，期限／责任／信号，不无限滚动拖延；辅助保护也有边界，独立依据与权限，不借名扩大管辖；构造：2单位/天，等待3天新增6，非零成本不自动授权。全图为规范与教学构造；暂停、观察与保护都须按各自对象和有效依据判断。","caption":"全图为规范与教学构造；暂停、观察与保护都须按各自对象和有效依据判断。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。后续可展开等待时钟与重开记录，不能自动将时间经过当作批准行动。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节讨论规范上的相称暂停与持续责任；缺少现实义务和权限档案，不以未经核实事件认证合法不作为或干预，使用清楚标识的教学构造。"},"openQuestions":["实际损害、义务、恢复过程、可用保护及权限尚需逐案材料；当前没有现实处置结论。"],"taskId":"S-12-14","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2641—2646行；每节精确范围见sourceRefs","claim_support":["12.14：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-14/lecture.md","sourcesPath":"/reading-assets/S-12-14/sources.json","sourceSlicePath":"/reading-assets/S-12-14/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-14/diagrams.md"},"12.15":{"title":"12.15　本部分的停止位置","lead":"本部分不是停在“什么都不知道”，而是停在能够负责的输出上限：有登记的条件前瞻、理由完整的分析推荐，以及与现实采用资格分开的选择记录。","explanation":["原文定位：第2647—2652行；原文锚点 section-12-15；短引文：‘不能把模型准确率兑换成统治资格’。本题源切片逐字附后，讲解与原文分开。","条件前瞻层可以发布带目标、期限、简单基线、早期与反向信号、校准和结果回写的判断。它仍依赖条件与证据，不保证未来。缺少相应登记时可以保留情景推演或解释，不能把复杂路径叙述包装成已经验证的前瞻。","有限选择层在规范、保护与授权明确时，可以比较行动、延迟、试探、退出和不行动，给出有条件、可撤回的选择记录。每项代价、受影响位置、反方意见与改判条件都是结论的一部分，不应藏在附录或因为不是主因而删掉。","尚未取得执行授权时，分析仍可以完成：只要证据与明确规范足以支持某项取舍，就给供审议的首选、否决或暂缓理由，并完整说明选项和分配后果。现实采用状态另行登记，不能把“无权执行”误读为“不能形成任何有依据的建议”。","该层不能消除价值冲突，也不能替代法律、专业规范、受影响者参与与现实授权。预测准只说明某项描述能力，复杂或高置信都不产生治理他人的资格；框架检查通过也不自动决定外部制度的法律效力。","§13.10九闸（2814—2831行）把边界落实为工具输出：DF6未过回到情景推演；DF7缺失暂停它所阻断的推荐，保留独立评价与明示前提的条件建议；DF8未过移交而不执行；DF9保留失败并追加版本。这是限定具体结论和动作，不是一项失败就删除全部已成立内容。","§16.22（3532—3537行）管理对象、变量、复杂度、校准和权力五类债，越过预定门槛可缩小、降级、暂停或退役。前瞻登记必须保留成功、失败、未决、目标失效与无法评价，不能只展示命中；复杂模型长期不优于简单基线时，增益声明要降级。","§16.24（3546—3553行）的替代机制要求比较判断质量与总负担，并保留任务、输入截止、资源与评价口径。没有实际比较时，既不能宣称框架更好，也不能声称已经证明等效或无用。退役时须移交仍有效的记录、责任、申诉与补救，而不是删去模型及其造成的后果。","停止记录应说清已完成哪种判断、哪些问题仍未知、哪项缺口阻断何种输出、下一次复核的触发和责任。撤回不可靠断言与继续既有保护可以并行，停止主模型的新用途不等停止对旧后果负责。"],"distinctions":[{"leftTitle":"完成分析推荐","leftText":"条件、证据、规范和取舍足够清楚。","rightTitle":"完成现实采用","rightText":"还需有效权限、保护、程序和实际执行链。"},{"leftTitle":"停止位置","leftText":"在证据或权限边界留下准确输出。","rightTitle":"全盘不回答","rightText":"不应删去独立成立的判断与建议。"},{"leftTitle":"准确率提高","leftText":"某目标上的预测表现改善。","rightTitle":"权力扩大","rightText":"必须有独立现实依据，不能兑换。"},{"leftTitle":"退役模型","leftText":"停止相关新用途并移交记录。","rightTitle":"责任退场","rightText":"旧伤害、申诉和补救仍需承接。"}],"boundaries":["未登记的情景路径不能以未来必然语气发布。","没有执行授权仍可分析推荐，但不能用祈使语气伪装执行命令。","治理门不能代替领域法律或专业判断，本讲不作具体法律结论。","无实际比较不得宣称性能优势、等效或无用；形式完整不等效果认证。"],"questions":["DF6没过仍能交付什么？","DF8没过会抹掉已有分析推荐吗？","正确率从0.7到0.9为何不允许修改A？","退役时何种责任不能消失？"],"diagramPath":"/reading-assets/S-12-15/figures/section-12-15.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.15","start_line":2647,"end_line":2652,"startLine":2647,"endLine":2652}],"outputId":"section-12-15","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["核当前是解释、推演、已登记前瞻、分析推荐还是现实采用，各自限定输出。","给出证据与明确规范足以支持的完整判断，不因权限未到而取消分析。","执行资格独立核，不能以准确率、复杂度或框架状态替代现实授权。","对应DF6—DF9和治理门处理缺口、降级、暂停与退役。","保存失败和责任、说明停止范围与下一次复核，不用停止抹去后果。"],"teachingExamples":[{"title":"教学构造：一份诚实的停止说明","text":"虚构输出写：现有资料支持比较方案A与B，在已明示保护和成本前提下分析首选A；反方是A可能增加某组维护负担，若该负担超过约定上限则改选B或缩小范围。当前主体对A执行的权限记录缺失，因此分析已完成、执行不获准；下一步移交适格主体核权限与承担条件。这样比只写“无法决定”保留更多有用内容，也没有擅自执行。","assumptions":"方案、角色和上限全为教学设定，没有现实动作或权限判定。","boundary":"若规范本身还未知，则不能伪装已明示；只能给各规范下的条件建议或明确待定部分。"},{"title":"形式构造：预测能力与授权集合相互独立","text":"设模型M1与M2在构造测试中正确率分别0.7和0.9，而主体的有效授权动作集合J均为{读取A}。无论模型得分哪一个，修改A都不属于J。若有效外部授权后来加入修改A，权限变化来自新授权，而不是0.2的准确率增量。","assumptions":"正确率、模型、对象和授权均为形式构造，不是实际测试或真实账户权限。","boundary":"此例不主张准确率无价值，只说明它不改变权限集合。"},{"title":"教学构造：退役仍须移交后果","text":"虚构复杂模型在相称长期比较中失去优势，治理决定停止其新预测。需要保留原预测和失败、标明哪些结论降级，并把尚未处理的申诉与补救交给有能力的责任方。单纯删除模型文件不能证明旧错误已纠正或受影响者已得到补救。","assumptions":"退役条件及结果是教学假设，未声称已比较或退役任何真实模型。","boundary":"现实移交要有接受方、范围、时限与完成验证，不能靠一句交接完毕。"}],"counterexamples":[{"identity":"constructed_boundary","text":"模型更准，因此可以扩大监控和处置范围。","effect":"准确率与权限是不同量，新增用途仍须独立依据。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"执行权限不足，所以只能给问题清单不能给首选。","effect":"可在已明确证据和规范下给条件首选与完整理由，执行身份另列。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"模型已退役，所以历史失败和申诉也可删除。","effect":"退役须保留责任链并移交补救，不消除旧后果。","sourceIds":["theory"]}],"questionAnswers":[{"question":"DF6没过仍能交付什么？","answer":"解释或情景推演及缺口说明，不能冒充已登记前瞻。","basis":"本节原文及上述公开推导"},{"question":"DF8没过会抹掉已有分析推荐吗？","answer":"不会，独立成立的供审议分析可保留，但不能发可执行指令。","basis":"本节原文及上述公开推导"},{"question":"正确率从0.7到0.9为何不允许修改A？","answer":"构造授权集合始终仅含读取A，预测分数不改权限。","basis":"本节原文及上述公开推导"},{"question":"退役时何种责任不能消失？","answer":"旧来源与失败记录、申诉、影响追踪、纠错及补救承接。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-15/figures/section-12-15.png","alt":"条件前瞻，目标／期限／基线，信号／校准／回写；完整分析推荐，规范／取舍／反方，分配／代价／改判；现实采用另核，外部授权与保护，不能由准确率兑换；DF6未过：情景，DF7缺口：局部暂停，DF8未过：不执行；仍保留成立内容，条件建议可完成，不降成空问题清单；治理可降级退役，失败／申诉／补救，继续有责任承接。输出边界不是现实授权来源；模型暂停或退役不使既有后果与补救责任消失。","caption":"输出边界不是现实授权来源；模型暂停或退役不使既有后果与补救责任消失。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。后续可选择门缺口显示被阻断的具体输出，不能一键删除所有既有分析。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节总结输出与治理责任，以公开的形式权限例和教学停止记录说明；未取得真实治理决定与完整比较资料，不虚构性能或退役成效。"},"openQuestions":["具体运行应在哪一层停止取决于实际合同、证据与外部授权，本文没有现实运行可代为签发资格。"],"taskId":"S-12-15","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2647—2652行；每节精确范围见sourceRefs","claim_support":["12.15：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"connections","title":"原书工具九闸与前瞻退役治理","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§13.10第2814—2831行；§16.22第3532—3537行；§16.24第3546—3553行","claim_support":["DF6—DF9输出边界、五类治理债、记录保存和退役替代责任"],"limits":["理论程序解释，未测试实际工具效果，也不认证现实法律效力或授权。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-15/lecture.md","sourcesPath":"/reading-assets/S-12-15/sources.json","sourceSlicePath":"/reading-assets/S-12-15/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-15/diagrams.md"},"12.16":{"title":"12.16　面向读者的发布格式","lead":"发布不是把完整分析缩成一句好听结论，而是让读者看清当前判断、全部已经做过的实质比较，以及哪些条件限制它的用途。开头可以直接，后文仍要完整。","explanation":["原文定位：第2653—2670行；原文锚点 section-12-16；短引文：‘摘要、附件链接与覆盖标记不能替代正文论证’。本题源切片逐字附后，讲解与原文分开。","默认交付完整分析，开头先给当前判断和范围，再展开条件、证据与不确定性。结论前置不等只给结论；摘要、附件地址或“已覆盖”标签不能替代可见正文论证。条件也不能藏在脚注，读者理解结论时就应看到其边界。","按输出类型保留适用字段：当前信息截止、目标与期限、对象和圈层范围、简单基线、全部已经开展的实质路径比较、每条路径的成立条件、早期与反向信号、表达强度、暂停和下一次复核。某字段确不适用可说明原因，不应为完整外观编造概率、真实案例或执行状态。","不能因为某分支不改变主结论、不是决定性理由或看来次要，就删掉已经开展的实质分析。这样的删减会隐藏结论的依赖、反方和适用边界；读者需要知道为什么其他方案被保留、降级或排除，而不只是看到胜出的那条。","只有用户明确要求简答或规定较短篇幅时才压缩可见答案，仍保存完整分析。超过单次容量时按章节连续交付，提供完整文件并明说尚未交付范围；不是发一个摘要后把剩余正文承诺成永远看不到的附件。完成标记也不能替尚未交付的内容。","有限选择发布须明确已经进入规范层，列价值前提、决定主体、受影响位置、保护底板、可选方案、行动和不行动的分配后果、授权状态、行动上限、停止、回滚与补救。可以先给分析推荐，但后面完整交代理由、接受或排除每项方案的依据、代价、反对意见和改判条件。","未获执行权限时，应准确写“供审议，现实执行尚未获准”，避免用“立即实施”等祈使包装越权；但不能因此抹掉已经有依据的分析取舍，退回只有疑问没有判断的清单。权限状态是推荐的用途边界，不是禁止思考。","原表五类表述各有上限。仅解释可说现有证据支持某机制并保留另一机制，不能说下一步必然发生；仅推演可说条件持续时路径获支持，不能说未来已确定；已登记前瞻可给期限内的有据比较但不得隐藏基线与失败条件；规范或授权尚未通过可给明确前提的分析推荐，不可称立即执行；外部授权成立时只能说具体记录允许某主体在上限内行动，授权不能归因于模型。","“模型认为”不能代替证据责任，应说依据是什么、怎样推导、哪些反例仍在、有哪些未知。人格候选不能在发布中变成人格事实，模拟不能变现实事件，概率不能被读成保证，方案比较不能借排版变成命令。","发布后发现读者误读，发布者有更正责任：明确误读点、原条件、正确用途与受影响范围，必要时暂停下游使用，并依实际权限落实更正或撤回。所有更新以新版本追加，原题名、概率或排序、期限和失败记录可追踪。更正文本已生成不等所有下游读者和系统已收到，也不等损害已修复。"],"distinctions":[{"leftTitle":"结论前置","leftText":"让读者先知道当前判断及范围。","rightTitle":"删成结论","rightText":"省略证据、反方与已做比较，破坏完整性。"},{"leftTitle":"完整文件","leftText":"承载全文并方便回查。","rightTitle":"附件链接替正文","rightText":"不能用地址冒充已经展开的论证。"},{"leftTitle":"表达强度","leftText":"与证据和输出合同匹配。","rightTitle":"语气自信","rightText":"不能凭措辞制造概率或确定性。"},{"leftTitle":"条件推荐","leftText":"有取舍但用途限定供审议。","rightTitle":"可执行决定","rightText":"需要有效外部权限与全部适用条件。"},{"leftTitle":"更正版本发布","leftText":"新的准确表述已经形成或送达某范围。","rightTitle":"全部后果修复","rightText":"下游与受影响者仍要分别验证。"}],"boundaries":["本文示范发布稿为教学文本，没有真实预测、现实授权或对外发布行为。","简洁可以来自结构清楚，不应来自隐藏条件或删反方。","已授权的范围仍有限且会到期，模型不是授权来源。","旧错误与失败须保留可追踪关系，不能用新版本制造从未出错的假象。"],"questions":["何时可以压缩可见答案？","教学队列两路径终点为何8与4？","未授权如何避免既越权又无用？","读者把条件说成保证时如何处理？"],"diagramPath":"/reading-assets/S-12-16/figures/section-12-16.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"12.16","start_line":2653,"end_line":2670,"startLine":2653,"endLine":2670}],"outputId":"section-12-16","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["开头给当前判断和范围，正文完整展开适用字段与全部已做实质比较。","按解释、推演、前瞻、规范分析及外部授权状态控制措辞。","有限选择明确价值、分配、保护、首选、反方、代价与改判，执行资格单列。","用户要求简答才压缩；超容量分章连续交付并说明剩余范围。","发现误读就相称更正，追加版本并核下游状态，不覆盖旧记录。"],"teachingExamples":[{"title":"教学构造：一份小型而完整的条件推演发布稿","text":"当前判断：仅在下面明示条件下，虚构队列两小时末积压可能为8或4，暂不作现实概率或路径排序。范围：对象仅为教学队列，截止t=0，初值6；没有真实圈层资料，圈层对象与分组增益不作声明。目标：比较t=2积压；简单基线保留处理每小时1、到件2，得到7再8。路径A与基线相同，条件是到件2且处理1持续两小时；早期信号为第一小时同口径记录净增1，反向信号为处理能力已实际提高。路径B处理每小时3、到件仍2，得到5再4；条件是扩容真实到位并持续，早期信号为实际完成3，反向信号为只有计划没有执行或资源撤回。两路径均为构造，不把申请等同实现。表达强度：只有条件计算，无现实校准，不发布命中率。暂停：初值、到件或完成记录未知时暂停依赖它的计算，独立资料仍可分析。复核：t=1核条件，t=2按原合同追加实际结果；若真实结果不存在就保留教学身份，不伪造结果。","assumptions":"全部对象、数值、时刻与观察方案人为构造；这是发布文本示范，未向任何实际对象收集数据。","boundary":"标题必须保持仅推演，不得改成“未来积压必降至4”；本稿没有规范目标，不能附带自动扩容命令。"},{"title":"教学构造：给出首选同时明确未授权","text":"当前分析推荐：在明示“降低积压且不挤占已承诺服务容量”的教学目标下，优先审议独立增援方案A；若增援会占用他组已承诺容量，则撤回首选并比较分时方案B。A的代价是新增预算和维护负担，B的代价是等待更久；明确不行动C保留现有服务但积压可能继续增长。反方指出A资源尚未落实，这一异议足以阻断现实采用，不能用预计收益抵销。决定主体和授权尚待有效外部记录，当前仅供审议。保护须覆盖各受影响组、申诉和可退出性；停止条件包括挤占既有服务或监测失真，回滚要恢复资源安排并核实际服务，补救另看已发生延迟。下一次复核以资源及权限材料到达为触发，当前不执行。","assumptions":"三方案和全部目标条件是教学构造，无现实预算、人员或执行器。","boundary":"没有提供实际审批通过或真实保护机制，文字模板不能充作有效授权记录。"},{"title":"教学构造：更正误读必须追加","text":"假设原教学稿v1题为“若处理3持续两小时，积压为4”，读者却把它转述成“任何情况下都会降到4”。v2应保留v1并追加：该结论依赖初值6、到件2、实际处理3和两小时时窗；若处理仍1则终点8。更正需说明误读传播到哪里、哪些下游使用待核；不能只把原题改掉而隐去旧传播。","assumptions":"版本、读者与传播全部假设，没有实际对外发布或错误传播。","boundary":"现实更正范围需有材料与权限，发送更正本身不证明全部下游已更新。"}],"counterexamples":[{"identity":"constructed_boundary","text":"次要路径不影响首选，可以删除已经完成的分析。","effect":"原要求保留已开展的实质比较，使依赖、反方和改判理由可见。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"无执行权限，只能输出若干问题。","effect":"可以完整给明示前提下的条件首选与理由，但执行状态单列。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"模型认为有效，足以代替来源和论证。","effect":"模型语气不提供证据责任，须说明材料、推理和边界。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"新版本纠正后，可以覆盖旧概率与失败记录。","effect":"更新只能追加并保持旧标题、概率、期限和失败可追踪。","sourceIds":["theory"]}],"questionAnswers":[{"question":"何时可以压缩可见答案？","answer":"用户明确要求简答或规定短篇幅时，仍保存完整分析；容量不足则分章连续交付。","basis":"本节原文及上述公开推导"},{"question":"教学队列两路径终点为何8与4？","answer":"初值6，到件2；处理1每小时净增1，两小时8；处理3每小时净减1，两小时4。","basis":"本节原文及上述公开推导"},{"question":"未授权如何避免既越权又无用？","answer":"先给有依据的供审议推荐，再完整交代规范、取舍、反方、代价、改判和现实采用缺口。","basis":"本节原文及上述公开推导"},{"question":"读者把条件说成保证时如何处理？","answer":"追加更正条件与用途，保留原记录，核传播范围及必要的下游纠正，不能利用误读扩张影响。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-12-16/figures/section-12-16.png","alt":"先给判断与范围，解释／推演／前瞻，推荐／授权分开；完整展开实质比较，条件／证据／反方，信号／基线／期限；有限选择另列，规范／分配／保护，权限／停止／补救；用户要求才简答，超容量分章交付，明说尚未交付范围；不能用链接或标签，替代正文论证，不藏次要实质分支；误读须更正，版本只追加，旧期限与失败保留。示范发布稿均为教学文本，未作真实预测、外部发布、读者测试或执行授权。","caption":"示范发布稿均为教学文本，未作真实预测、外部发布、读者测试或执行授权。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。后续网站可折叠导航但不得删除内容；所有展开区保留完整条件、反方与版本关系。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节规定发布责任，使用完整教学发布稿可直接检验措辞与字段；未进行真实读者测试、外部发布或测量传播效果。"},"openQuestions":["示范稿的可读性尚未经过真实读者测试；实际对外发布须依据具体来源、受众、权限和保护范围。"],"taskId":"S-12-16","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第2653—2670行；每节精确范围见sourceRefs","claim_support":["12.16：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-12-16/lecture.md","sourcesPath":"/reading-assets/S-12-16/sources.json","sourceSlicePath":"/reading-assets/S-12-16/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-12-16/diagrams.md"}}},"headers":[],"relativePath":"theory/part-12.md","filePath":"theory/part-12.md"}'),c={name:"theory/part-12.md"};function l(u,t,p,h,m,f){const e=r("SectionLesson");return o(),n("div",null,[t[0]||(t[0]=s("",1)),i(e,{section:"intro-12-part"}),t[1]||(t[1]=s("",1)),i(e,{section:"12.1"}),t[2]||(t[2]=s("",1)),i(e,{section:"12.2"}),t[3]||(t[3]=s("",1)),i(e,{section:"12.2.1"}),t[4]||(t[4]=s("",1)),i(e,{section:"12.2.2"}),t[5]||(t[5]=s("",1)),i(e,{section:"12.3"}),t[6]||(t[6]=s("",1)),i(e,{section:"12.4"}),t[7]||(t[7]=s("",1)),i(e,{section:"12.5"}),t[8]||(t[8]=s("",1)),i(e,{section:"12.6"}),t[9]||(t[9]=s("",1)),i(e,{section:"12.7"}),t[10]||(t[10]=s("",1)),i(e,{section:"12.8"}),t[11]||(t[11]=s("",1)),i(e,{section:"12.9"}),t[12]||(t[12]=s("",1)),i(e,{section:"12.10"}),t[13]||(t[13]=s("",1)),i(e,{section:"12.10.1"}),t[14]||(t[14]=s("",1)),i(e,{section:"12.10.2"}),t[15]||(t[15]=s("",1)),i(e,{section:"12.11"}),t[16]||(t[16]=s("",1)),i(e,{section:"12.12"}),t[17]||(t[17]=s("",1)),i(e,{section:"12.13"}),t[18]||(t[18]=s("",1)),i(e,{section:"12.14"}),t[19]||(t[19]=s("",1)),i(e,{section:"12.15"}),t[20]||(t[20]=s("",1)),i(e,{section:"12.16"}),t[21]||(t[21]=d("div",{class:"theory-source"},null,-1))])}const b=a(c,[["render",l]]);export{g as __pageData,b as default};
